insert into item_catalog (id, data) values ('srd-2024_ammunition-plus-one', '{"h":1,"w":1,"icon":"fa-khanda","name":"Ammunition (+1)","tags":["weapon","uncommon","magic+1"],"graph":[{"id":"srd-2024_ammunition-plus-one_bonus","op":"add","label":"+1 magic ammunition","value":"1"}],"flavor":"You have a bonus to attack rolls and damage rolls made with this piece of magic ammunition. The bonus is determined by the rarity of the ammunition. Once it hits a target, the ammunition is no longer magical. This ammunition is typically found or sold in quantities of ten or twenty pieces. Ten pieces of this ammunition are equivalent in value to a potion of the same rarity.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_ammunition-plus-one","category":"weapon"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
