insert into item_catalog (id, data) values ('srd-2024_amulet-of-health', '{"h":1,"w":1,"icon":"fa-gem","name":"Amulet of Health","slot":"neck","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires attunement","flavor":"Your Constitution is 19 while you wear this amulet. It has no effect on you if your Constitution is 19 or higher without it.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_amulet-of-health","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_amulet-of-proof-against-detection-and-location', '{"h":1,"w":1,"icon":"fa-gem","name":"Amulet of Proof against Detection and Location","slot":"neck","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While wearing this amulet, you can''t be targeted by Divination spells or perceived through magical scrying sensors unless you allow it.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_amulet-of-proof-against-detection-and-location","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_amulet-of-the-planes', '{"h":1,"w":1,"icon":"fa-gem","name":"Amulet of the Planes","slot":"neck","tags":["misc","wondrous-item","very-rare","attunement"],"attune":"Requires attunement","flavor":"While wearing this amulet, you can take a Magic action to name a location that you are familiar with on another plane of existence. Then make a DC 15 Intelligence (Arcana) check. On a successful check, you cast *Plane Shift*. On a failed check, you and each creature and object within 15 feet of you travel to a random destination determined by rolling 1d100 and consulting the following table.\n\n| 1d100 | Destination\n|-------|-----------------------------------------|\n| 01–60 | Random location on the plane you named  |\n| 61–70 | Random location on an Inner Plane determined by rolling 1d6: on a **1,** the Plane of Air; on a **2,** the Plane of Earth; on a **3,** the Plane of Fire; on a **4,** the Plane of Water; on a **5,** the Feywild; on a **6,** the Shadowfell |\n| 71–80 | Random location on an Outer Plane determined by rolling 1d8: on a **1,** Arborea; on a **2,** Arcadia; on a **3,** the Beastlands; on a **4,** Bytopia; on a **5,** Elysium; on a **6,** Mechanus; on a **7,** Mount Celestia; on an **8,** Ysgard |\n| 81–90 | Random location on an Outer Plane determined by rolling 1d8: on a **1,** the Abyss; on a **2,** Acheron; on a **3,** Carceri; on a **4,** Gehenna; on a **5,** Hades; on a **6,** Limbo; on a **7,** the Nine Hells; on an **8,** Pandemonium |\n| 91–00 | Random location on the Astral Plane     |","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_amulet-of-the-planes","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_animated-shield', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Animated Shield","slot":"armor","tags":["armor","very-rare","attunement"],"attune":"Requires attunement","flavor":"While holding this Shield, you can take a Bonus Action to cause it to animate. The Shield leaps into the air and hovers in your space to protect you as if you were wielding it, leaving your hands free. The Shield remains animate for 1 minute, until you take a Bonus Action to end this effect, or until you die or have the Incapacitated condition, at which point the Shield falls to the ground or into your hand if you have one free.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_animated-shield","category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_antitoxin', '{"h":1,"w":1,"icon":"fa-flask-vial","name":"Antitoxin","tags":["consumable","potion","common"],"value":50,"flavor":"As a Bonus Action, you can drink a vial of Antitoxin to gain Advantage on saving throws to avoid or end the Poisoned condition for 1 hour. abo","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_antitoxin","category":"consumable","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_apparatus-of-the-crab', '{"h":1,"w":1,"icon":"fa-cube","name":"Apparatus of the Crab","tags":["misc","wondrous-item","legendary"],"flavor":"This item first appears to be a sealed iron barrel weighing 500 pounds. The barrel has a hidden catch, which can be found with a successful DC 20 Intelligence (Investigation) check. Releasing the catch unlocks a hatch at one end of the barrel, allowing two Medium or smaller creatures to crawl inside. Ten levers are set in a row at the far end, each in a neutral position, able to move up or down. When certain levers are used, the apparatus transforms to resemble a giant lobster.\n\nThe *Apparatus of the Crab* is a Large object with the following statistics: AC 20; HP 200; Speed 30 ft., Swim 30 ft. (or 0 ft. for both if the legs aren''t extended); Immunity to Poison and Psychic damage.\n\nTo be used as a vehicle, the apparatus requires one pilot. While the apparatus''s hatch is closed, the compartment is airtight and watertight. The compartment holds enough air for 10 hours of breathing, divided by the number of breathing creatures inside.\n\nThe apparatus floats on water. It can also go underwater to a depth of 900 feet. Below that, the vehicle takes 2d6 Bludgeoning damage each minute from pressure.\n\nA creature in the compartment can take a Utilize action to move as many as two of the apparatus''s levers up or down. After each use, a lever goes back to its neutral position. Each lever, from left to right, functions as shown in the Apparatus of the Crab Levers table.\n\nTable: Apparatus of the Crab Levers\n\n| Lever | Up                                                     | Down                                       |\n|-------|--------------------------------------------------------|--------------------------------------------|\n| 1     | Legs extend, allowing the apparatus to walk and swim.  | Legs retract, reducing the apparatus''s Speed and Swim Speed to 0 and making it unable to benefit from bonuses to speed. |\n| 2     | Forward window shutter opens.                          | Forward window shutter closes.             |\n| 3     | Side window shutters open (two per side).              | Side window shutters close (two per side). |\n| 4     | Two claws extend from the front side of the apparatus. | The claws retract.                         |\n| 5     | Each extended claw makes the following melee attack: +8 to hit, reach 5 ft. *Hit:* 7 (2d6) Bludgeoning damage. | Each extended claw makes the following melee attack: +8 to hit, reach 5 ft. *Hit:* The target has the Grappled condition (escape DC 15). |\n| 6     | The apparatus walks or swims forward provided its legs are extended. | The apparatus walks or swims backward provided its legs are extended. |\n| 7     | The apparatus turns 90 degrees counterclockwise provided its legs are extended. | The apparatus turns 90 degrees clockwise provided its legs are extended. |\n| 8     | Eyelike fixtures emit Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. | The light turns off. \n| 9     | The apparatus sinks up to 20 feet if it''s in liquid.   | The apparatus rises up to 20 feet if it''s in liquid. |\n| 10    | The rear hatch unseals and opens.                      | The rear hatch closes and seals.           |","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_apparatus-of-the-crab","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_armor-of-invulnerability', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Armor of Invulnerability","slot":"armor","tags":["armor","legendary","attunement"],"attune":"Requires attunement","flavor":"You have Resistance to Bludgeoning, Piercing, and Slashing damage while you wear this armor. Metal Shell. You can take a Magic action to give yourself Immunity to Bludgeoning, Piercing, and Slashing damage for 10 minutes or until you are no longer wearing the armor. Once this property is used, it can''t be used again until the next dawn.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_armor-of-invulnerability","category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_armor-of-resistance-breastplate', '{"h":2,"w":2,"icon":"fa-shield-halved","name":"Armor of Resistance (Breastplate)","slot":"armor","tags":["armor","rare","armor:medium"],"baseAc":14,"flavor":"You have Resistance to one type of damage while you wear this armor. The GM chooses the type or determines it randomly by rolling on the following table.\n\n| 1d10 | Damage Type |\n|---|---|\n|1|Acid|\n|2|Cold|\n|3|Fire|\n|4|Force|\n|5|Lightning|\n|6|Necrotic|\n|7| Poison|\n|8|Psychic|\n|9|Radiant|\n|10|Thunder|","rarity":"rare","source":"srd","weight":20,"srd_key":"srd-2024_armor-of-resistance-breastplate","acAddDex":true,"acDexCap":2,"category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
