insert into item_catalog (id, data) values ('srd-2024_armor-of-vulnerability-breastplate', '{"h":2,"w":2,"icon":"fa-shield-halved","name":"Armor of Vulnerability (Breastplate)","slot":"armor","tags":["armor","rare","armor:medium"],"baseAc":14,"flavor":"While wearing this armor, you have Resistance to one of the following damage types: Bludgeoning, Piercing, or Slashing. The GM chooses the type or determines it randomly. Curse. This armor is cursed, a fact that is revealed only when the Identify spell is cast on the armor or you attune to it. Attuning to the armor curses you until you are targeted by a Remove Curse spell or similar magic; removing the armor fails to end the curse. While cursed, you have Vulnerability to two of the three damage types associated with the armor (not the one to which it grants Resistance).","rarity":"rare","source":"srd","weight":20,"srd_key":"srd-2024_armor-of-vulnerability-breastplate","acAddDex":true,"acDexCap":2,"category":"armor"}'::jsonb)
