insert into item_catalog (id, data) values ('srd-2024_belt-of-giant-strength-cloud', '{"h":1,"w":1,"icon":"fa-cube","name":"Belt of Giant Strength (Cloud)","tags":["misc","wondrous-item","legendary","attunement"],"attune":"Requires attunement","flavor":"While wearing this belt, your Strength changes to a score granted by the belt. The type of giant determines the score (see the table below). The item has no effect on you if your Strength without the belt is equal to or greater than the belt''s score.\n\n| Belt                                    | Str. | Rarity    |\n|-----------------------------------------|------|-----------|\n| Belt of Giant Strength (hill)           | 21   | Rare      |\n| Belt of Giant Strength (frost or stone) | 23   | Very Rare |\n| Belt of Giant Strength (fire)           | 25   | Very Rare |\n| Belt of Giant Strength (cloud)          | 27   | Legendary |\n| Belt of Giant Strength (storm)          | 29   | Legendary |","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_belt-of-giant-strength-cloud","category":"misc"}'::jsonb)
