insert into item_catalog (id, data) values ('srd-2024_berserker-battleaxe', '{"h":1,"w":1,"icon":"fa-khanda","name":"Berserker Battleaxe","tags":["weapon","rare","slashing","topple","versatile","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your Hit Point maximum increases by 1 for each level you have attained. Curse. This weapon is cursed, and becoming attuned to it extends the curse to you. As long as you remain cursed, you are unwilling to part with the weapon, keeping it within reach at all times. You also have Disadvantage on attack rolls with weapons other than this one. Whenever another creature damages you while the weapon is in your possession, you must succeed on a DC 15 Wisdom saving throw or go berserk. This berserk state ends when you start your turn and there are no creatures within 60 feet of you that you can see or hear. While berserk, you regard the creature nearest to you that you can see or hear as your enemy. If there are multiple possible creatures, choose one at random. On each of your turns, you must move as close to the creature as possible and take the Attack action, targeting the creature. If you''re unable to get close enough to the creature to attack it with the weapon, your turn ends after you''ve used up all your available movement. If the creature dies or can no longer be seen or heard by you, the next nearest creature that you can see or hear becomes your new target.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_berserker-battleaxe","category":"weapon","damageDice":"1d8","properties":["Topple","Versatile"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_berserker-greataxe', '{"h":3,"w":1,"icon":"fa-khanda","name":"Berserker Greataxe","tags":["weapon","rare","slashing","cleave","heavy","two-handed","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your Hit Point maximum increases by 1 for each level you have attained. Curse. This weapon is cursed, and becoming attuned to it extends the curse to you. As long as you remain cursed, you are unwilling to part with the weapon, keeping it within reach at all times. You also have Disadvantage on attack rolls with weapons other than this one. Whenever another creature damages you while the weapon is in your possession, you must succeed on a DC 15 Wisdom saving throw or go berserk. This berserk state ends when you start your turn and there are no creatures within 60 feet of you that you can see or hear. While berserk, you regard the creature nearest to you that you can see or hear as your enemy. If there are multiple possible creatures, choose one at random. On each of your turns, you must move as close to the creature as possible and take the Attack action, targeting the creature. If you''re unable to get close enough to the creature to attack it with the weapon, your turn ends after you''ve used up all your available movement. If the creature dies or can no longer be seen or heard by you, the next nearest creature that you can see or hear becomes your new target.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_berserker-greataxe","category":"weapon","damageDice":"1d12","properties":["Cleave","Heavy","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
