insert into item_catalog (id, data) values ('srd-2024_boots-of-elvenkind', '{"h":1,"w":1,"icon":"fa-shoe-prints","name":"Boots of Elvenkind","slot":"boots","tags":["misc","wondrous-item","uncommon"],"flavor":"While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have Advantage on Dexterity (Stealth) checks.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_boots-of-elvenkind","category":"misc"}'::jsonb)
