  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_boots-of-speed', '{"h":1,"w":1,"icon":"fa-shoe-prints","name":"Boots of Speed","slot":"boots","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires attunement","flavor":"While you wear these boots, you can take a Bonus Action to click the boots'' heels together. If you do, the boots double your Speed, and any creature that makes an Opportunity Attack against you has Disadvantage on the attack roll. If you click your heels together again, you end the effect. When you''ve used the boots'' property for a total of 10 minutes, the magic ceases to function for you until you finish a Long Rest.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_boots-of-speed","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_boots-of-striding-and-springing', '{"h":1,"w":1,"icon":"fa-shoe-prints","name":"Boots of Striding and Springing","slot":"boots","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While you wear these boots, your Speed becomes 30 feet unless your Speed is higher, and your Speed isn''t reduced by you carrying weight in excess of your carrying capacity or wearing Heavy Armor. Once on each of your turns, you can jump up to 30 feet by spending only 10 feet of movement.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_boots-of-striding-and-springing","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_boots-of-the-winterlands', '{"h":1,"w":1,"icon":"fa-shoe-prints","name":"Boots of the Winterlands","slot":"boots","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"These furred boots are snug and feel warm. While wearing them, you gain the following benefits. Cold Resistance. You have Resistance to Cold damage and can tolerate temperatures of 0 degrees Fahrenheit or lower without any additional protection. Winter Strider. You ignore Difficult Terrain created by ice or snow.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_boots-of-the-winterlands","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_bottle-glass', '{"h":1,"w":1,"icon":"fa-cube","name":"Bottle, Glass","tags":["misc","adventuring-gear","common"],"value":2,"flavor":"A Glass Bottle holds up to 1 0.5 pints.","rarity":"common","source":"srd","weight":2,"srd_key":"srd-2024_bottle-glass","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_bowl-of-commanding-water-elementals', '{"h":1,"w":1,"icon":"fa-cube","name":"Bowl of Commanding Water Elementals","tags":["misc","wondrous-item","rare"],"flavor":"While this bowl is filled with water and you are within 5 feet of it, you can take a Magic action to summon a Water Elemental. The elemental appears in an unoccupied space as close to the bowl as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The bowl can''t be used this way again until the next dawn. The bowl is about 1 foot in diameter and half as deep. It holds about 3 gallons.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_bowl-of-commanding-water-elementals","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_bracers-of-archery', '{"h":1,"w":1,"icon":"fa-mitten","name":"Bracers of Archery","slot":"gloves","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While wearing these bracers, you have proficiency with the Longbow and Shortbow, and you gain a +2 bonus to damage rolls made with such weapons.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_bracers-of-archery","category":"misc"}'::jsonb)
