  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_brazier-of-commanding-fire-elementals', '{"h":1,"w":1,"icon":"fa-cube","name":"Brazier of Commanding Fire Elementals","tags":["misc","wondrous-item","rare"],"flavor":"While you are within 5 feet of this brazier, you can take a Magic action to summon a Fire Elemental. The elemental appears in an unoccupied space as close to the brazier as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The brazier can''t be used this way again until the next dawn.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_brazier-of-commanding-fire-elementals","category":"misc"}'::jsonb)
