insert into item_catalog (id, data) values ('srd-2024_caltrops', '{"h":1,"w":1,"icon":"fa-cube","name":"Caltrops","tags":["misc","adventuring-gear","common"],"value":1,"flavor":"As a Utilize action, you can spread Caltrops from their bag to cover a 5-foot-square area within 5 feet of yourself. A creature that enters this area for the first time on a turn must succeed on a DC 15 Dexterity saving throw or take 1 Piercing damage and have its Speed reduced to 0 until the start of its next turn. It takes 10 minutes to recover the Caltrops.","rarity":"common","source":"srd","weight":2,"srd_key":"srd-2024_caltrops","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_candle', '{"h":1,"w":1,"icon":"fa-fire","name":"Candle","tags":["misc","adventuring-gear","common"],"value":0.01,"flavor":"For 1 hour, a lit Candle sheds Bright Light in a 5-foot radius and Dim Light for an additional 5 feet.","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_candle","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_candle-of-invocation', '{"h":1,"w":1,"icon":"fa-fire","name":"Candle of Invocation","tags":["misc","wondrous-item","very-rare","attunement"],"attune":"Requires attunement","flavor":"This candle''s magic is activated when the candle is lit, which requires a Magic action. After burning for 4 hours, the candle is destroyed. You can snuff it out early for use at a later time. Deduct the time it burned in increments of 1 minute from its total burn time.\n\nWhile lit, the candle sheds Dim Light in a 30-foot radius. While you are within that light, you have Advantage on D20 Tests. In addition, a Cleric or Druid in the light can cast level 1 spells they have prepared without expending spell slots.\n\nAlternatively, when you light the candle for the first time, you can cast *Gate* with it. Doing so destroys the candle. The portal created by the spell links to a particular Outer Plane chosen by the GM or determined by rolling on the following table.\n\n| 1d100 | Outer Plane    |\n|-------|----------------|\n| 01–05 | Abyss          |\n| 06–10 | Acheron        |\n| 11–17 | Arborea        |\n| 18–25 | Arcadia        |\n| 26–33 | Beastlands     |\n| 34–41 | Bytopia        |\n| 42–46 | Carceri        |\n| 47–54 | Elysium        |\n| 55–59 | Gehenna        |\n| 60–64 | Hades          |\n| 65–69 | Limbo          |\n| 70–77 | Mechanus       |\n| 78–85 | Mount Celestia |\n| 86–90 | Nine Hells     |\n| 91–95 | Pandemonium    |\n| 96–00 | Ysgard         |","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_candle-of-invocation","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cape-of-the-mountebank', '{"h":1,"w":1,"icon":"fa-user-ninja","name":"Cape of the Mountebank","slot":"cloak","tags":["misc","wondrous-item","rare"],"flavor":"This cape smells faintly of brimstone. While wearing it, you can use it to cast Dimension Door as a Magic action. This property can''t be used again until the next dawn. When you teleport with that spell, you leave behind a cloud of smoke. The space you left is Lightly Obscured by that smoke until the end of your next turn.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_cape-of-the-mountebank","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_carpenters-tools', '{"h":1,"w":1,"icon":"fa-screwdriver-wrench","name":"Carpenter''s Tools (8 GP)","tags":["tool","tools","common"],"value":8,"flavor":"Ability: Strength. Utilize: Seal or pry open a door or container (DC 20). Craft: Club, Greatclub, Quarterstaff, Barrel, Chest, Ladder, Pole, Portable Ram, Torch","rarity":"common","source":"srd","weight":6,"srd_key":"srd-2024_carpenters-tools","category":"tool","valueUnit":"gp"}'::jsonb)
