insert into item_catalog (id, data) values ('srd-2024_carpet-of-flying', '{"h":1,"w":1,"icon":"fa-cube","name":"Carpet of Flying","tags":["misc","wondrous-item","very-rare"],"flavor":"You can make this carpet hover and fly by taking a Magic action and using the carpet''s command word. It moves according to your directions if you are within 30 feet of it.\n\nFour sizes of *Carpet of Flying* exist. The GM chooses the size of a given carpet or determines it randomly by rolling on the following table. A carpet can carry up to twice the weight shown on the table, but its Fly Speed is halved if it carries more than its normal capacity.\n\n| 1d100 | Size          | Capacity | Fly Speed |\n|-------|---------------|----------|-----------|\n| 01–20 | 3 ft. × 5 ft. | 200 lb.  | 80 feet   |\n| 21–55 | 4 ft. × 6 ft. | 400 lb.  | 60 feet   |\n| 56–80 | 5 ft. × 7 ft. | 600 lb.  | 40 feet   |\n| 81–00 | 6 ft. × 9 ft. | 800 lb.  | 30 feet   |","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_carpet-of-flying","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
