insert into item_catalog (id, data) values ('srd-2024_chime-of-opening', '{"h":1,"w":1,"icon":"fa-cube","name":"Chime of Opening","tags":["misc","wondrous-item","rare"],"flavor":"This hollow metal tube measures about 1 foot long and weighs 1 pound. As a Magic action, you can strike the chime to cast Knock. The spell''s customary knocking sound is replaced by the clear, ringing tone of the chime, which is audible out to 300 feet. The chime can be used 10 times. After the tenth time, it cracks and becomes useless.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_chime-of-opening","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_circlet-of-blasting', '{"h":1,"w":1,"icon":"fa-hat-wizard","name":"Circlet of Blasting","slot":"helmet","tags":["misc","wondrous-item","uncommon"],"flavor":"While wearing this circlet, you can cast Scorching Ray with it (+5 to hit). The circlet can''t cast this spell again until the next dawn.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_circlet-of-blasting","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_climbers-kit', '{"h":1,"w":1,"icon":"fa-screwdriver-wrench","name":"Climber''s Kit","tags":["tool","tools","common"],"value":25,"flavor":"A Climber''s Kit includes boot tips, gloves, pitons, and a harness. As a Utilize action, you can use the Climber''s Kit to anchor yourself; when you do, you can''t fall more than 25 feet from the anchor point, and you can''t move more than 25 feet from there without undoing the anchor as a Bonus Action.","rarity":"common","source":"srd","weight":12,"srd_key":"srd-2024_climbers-kit","category":"tool","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cloak-of-arachnida', '{"h":1,"w":1,"icon":"fa-user-ninja","name":"Cloak of Arachnida","slot":"cloak","tags":["misc","wondrous-item","very-rare","attunement"],"attune":"Requires attunement","flavor":"This fine garment is made of black silk interwoven with faint, silvery threads. While wearing it, you gain the following benefits. Poison Resistance. You have Resistance to Poison damage. Spider Climb. You have a Climb Speed equal to your Speed and can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free. Spider Walk. You can''t be caught in webs of any sort and can move through webs as if they were Difficult Terrain. Web. You can cast Web (save DC 13). The web created by the spell fills twice its normal area. Once used, this property can''t be used again until the next dawn.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_cloak-of-arachnida","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cloak-of-displacement', '{"h":1,"w":1,"icon":"fa-user-ninja","name":"Cloak of Displacement","slot":"cloak","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires attunement","flavor":"While you wear this cloak, it magically projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have Disadvantage on attack rolls against you. If you take damage, the property ceases to function until the start of your next turn. This property is suppressed while your Speed is 0.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_cloak-of-displacement","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cloak-of-elvenkind', '{"h":1,"w":1,"icon":"fa-user-ninja","name":"Cloak of Elvenkind","slot":"cloak","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While you wear this cloak, Wisdom (Perception) checks made to perceive you have Disadvantage, and you have Advantage on Dexterity (Stealth) checks.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_cloak-of-elvenkind","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cloak-of-protection', '{"h":1,"w":1,"icon":"fa-user-ninja","name":"Cloak of Protection","slot":"cloak","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"You gain a +1 bonus to Armor Class and saving throws while you wear this cloak.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_cloak-of-protection","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cloak-of-the-bat', '{"h":1,"w":1,"icon":"fa-user-ninja","name":"Cloak of the Bat","slot":"cloak","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires attunement","flavor":"While wearing this cloak, you have Advantage on Dexterity (Stealth) checks. In an area of Dim Light or Darkness, you can grip the edges of the cloak and use it to gain a Fly Speed of 40 feet. If you ever fail to grip the cloak''s edges while flying in this way, or if you are no longer in Dim Light or Darkness, you lose this Fly Speed. While wearing the cloak in an area of Dim Light or Darkness, you can cast Polymorph on yourself, shape-shifting into a Bat. While in that form, you retain your Intelligence, Wisdom, and Charisma scores. The cloak can''t be used this way again until the next dawn.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_cloak-of-the-bat","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cloak-of-the-manta-ray', '{"h":1,"w":1,"icon":"fa-user-ninja","name":"Cloak of the Manta Ray","slot":"cloak","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While wearing this cloak, you can breathe underwater, and you have a Swim Speed of 60 feet.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_cloak-of-the-manta-ray","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_clothes-fine', '{"h":1,"w":1,"icon":"fa-cube","name":"Clothes, Fine","tags":["misc","adventuring-gear","common"],"value":15,"flavor":"Fine Clothes are made of expensive fabrics and adorned with expertly crafted details. Some events and locations admit only people wearing these clothes.","rarity":"common","source":"srd","weight":6,"srd_key":"srd-2024_clothes-fine","category":"misc","valueUnit":"gp"}'::jsonb)
