insert into item_catalog (id, data) values ('srd-2024_cobblers-tools', '{"h":1,"w":1,"icon":"fa-screwdriver-wrench","name":"Cobbler''s Tools (5 GP)","tags":["tool","tools","common"],"value":5,"flavor":"Ability: Dexterity. Utilize: Modify footwear to give Advantage on the wearer''s next Dexterity (Acrobatics) check (DC 10). Craft: Climber''s Kit","rarity":"common","source":"srd","weight":5,"srd_key":"srd-2024_cobblers-tools","category":"tool","valueUnit":"gp"}'::jsonb)
