insert into item_catalog (id, data) values ('srd-2024_crystal-ball', '{"h":1,"w":1,"icon":"fa-gem","name":"Crystal Ball","tags":["misc","wondrous-item","very-rare","attunement"],"attune":"Requires attunement","flavor":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_crystal-ball","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_crystal-ball-of-mind-reading', '{"h":1,"w":1,"icon":"fa-gem","name":"Crystal Ball of Mind Reading","tags":["misc","wondrous-item","legendary","attunement"],"attune":"Requires attunement","flavor":"While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you can cast Detect Thoughts (save DC 17) targeting creatures you can see within 30 feet of the spell''s sensor. You don''t need to concentrate on this Detect Thoughts spell to maintain it during its duration, but it ends if the Scrying spell ends.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_crystal-ball-of-mind-reading","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_crystal-ball-of-telepathy', '{"h":1,"w":1,"icon":"fa-gem","name":"Crystal Ball of Telepathy","tags":["misc","wondrous-item","legendary","attunement"],"attune":"Requires attunement","flavor":"While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you can communicate telepathically with creatures you can see within 30 feet of the spell''s sensor. You can also cast Suggestion (save DC 17) through the sensor on one of those creatures. You don''t need to concentrate on this Suggestion to maintain it during its duration, but it ends if Scrying ends. You can''t cast Suggestion in this way again until the next dawn.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_crystal-ball-of-telepathy","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_crystal-ball-of-true-seeing', '{"h":1,"w":1,"icon":"fa-gem","name":"Crystal Ball of True Seeing","tags":["misc","wondrous-item","legendary","attunement"],"attune":"Requires attunement","flavor":"While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you have Truesight with a range of 120 feet centered on the spell''s sensor.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_crystal-ball-of-true-seeing","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cube-of-force', '{"h":1,"w":1,"icon":"fa-cube","name":"Cube of Force","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires attunement","flavor":"This cube is about an inch across. Each face has a distinct marking on it. You can press one of those faces, expend the number of charges required for it, and thereby cast the spell associated with it (save DC 17), as shown in the Cube of Force Faces table.\n\nThe cube starts with 10 charges, and it regains 1d6 expended charges daily at dawn.\n\nTable: Cube of Force Faces\n\n| Spell            | Charge Cost |\n|------------------|-------------|\n| Mage Armor       | 1           |\n| Shield           | 1           |\n| Tiny Hut         | 3           |\n| Private Sanctum  | 4           |\n| Resilient Sphere | 4           |\n| Wall of Force    | 5           |","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_cube-of-force","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_cubic-gate', '{"h":1,"w":1,"icon":"fa-cube","name":"Cubic Gate","tags":["misc","wondrous-item","legendary"],"flavor":"This cube is 3 inches across and radiates palpable magical energy. The six sides of the cube are each keyed to a different plane of existence, one of which is the Material Plane. The other sides are linked to planes determined by the GM. The cube has 3 charges and regains 1d3 expended charges daily at dawn. As a Magic action, you can expend 1 of the cube''s charges to cast one of the following spells using the cube. Gate. Pressing one side of the cube, you cast Gate, opening a portal to the plane of existence keyed to that side. Plane Shift. Pressing one side of the cube twice, you cast Plane Shift, transporting the targets to the plane of existence keyed to that side.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_cubic-gate","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_dagger', '{"h":1,"w":1,"icon":"fa-khanda","name":"Dagger","tags":["weapon","common","piercing","finesse","light","nick","thrown"],"type":"Piercing","value":2,"flavor":"A dagger.","rarity":"common","source":"srd","weight":1,"ability":"finesse","srd_key":"srd-2024_dagger","category":"weapon","valueUnit":"gp","damageDice":"1d4","properties":["Finesse","Light","Nick","Thrown"]}'::jsonb)
