insert into item_catalog (id, data) values ('srd-2024_dancing-scimitar', '{"h":1,"w":1,"icon":"fa-khanda","name":"Dancing Scimitar","tags":["weapon","very-rare","slashing","finesse","light","nick","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You can take a Bonus Action to toss this magic weapon into the air. When you do so, the weapon begins to hover, flies up to 30 feet, and attacks one creature of your choice within 5 feet of itself. The weapon uses your attack roll and adds your ability modifier to damage rolls. While the weapon hovers, you can take a Bonus Action to cause it to fly up to 30 feet to another spot within 30 feet of you. As part of the same Bonus Action, you can cause the weapon to attack one creature within 5 feet of the weapon. After the hovering weapon attacks for the fourth time, it flies back to you and tries to return to your hand. If you have no hand free, the weapon falls to the ground in your space. If the weapon has no unobstructed path to you, it moves as close to you as it can and then falls to the ground. It also ceases to hover if you grasp it or are more than 30 feet away from it.","rarity":"very-rare","source":"srd","weight":0,"ability":"finesse","srd_key":"srd-2024_dancing-scimitar","category":"weapon","damageDice":"1d6","properties":["Finesse","Light","Nick"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_dancing-shortsword', '{"h":1,"w":1,"icon":"fa-khanda","name":"Dancing Shortsword","tags":["weapon","very-rare","piercing","finesse","light","vex","attunement"],"type":"Piercing","attune":"Requires attunement","flavor":"You can take a Bonus Action to toss this magic weapon into the air. When you do so, the weapon begins to hover, flies up to 30 feet, and attacks one creature of your choice within 5 feet of itself. The weapon uses your attack roll and adds your ability modifier to damage rolls. While the weapon hovers, you can take a Bonus Action to cause it to fly up to 30 feet to another spot within 30 feet of you. As part of the same Bonus Action, you can cause the weapon to attack one creature within 5 feet of the weapon. After the hovering weapon attacks for the fourth time, it flies back to you and tries to return to your hand. If you have no hand free, the weapon falls to the ground in your space. If the weapon has no unobstructed path to you, it moves as close to you as it can and then falls to the ground. It also ceases to hover if you grasp it or are more than 30 feet away from it.","rarity":"very-rare","source":"srd","weight":0,"ability":"finesse","srd_key":"srd-2024_dancing-shortsword","category":"weapon","damageDice":"1d6","properties":["Finesse","Light","Vex"]}'::jsonb)
