insert into item_catalog (id, data) values ('srd-2024_dart-plus-1', '{"h":1,"w":1,"icon":"fa-khanda","name":"Dart (+1)","tags":["weapon","uncommon","piercing","finesse","thrown","vex","magic+1"],"type":"Piercing","graph":[{"id":"srd-2024_dart-plus-1_bonus","op":"add","label":"+1 magic weapon","value":"1"}],"flavor":"You have a bonus to attack rolls and damage rolls made with this magic weapon. The bonus is determined by the weapon''s rarity.","rarity":"uncommon","source":"srd","weight":1,"ability":"finesse","srd_key":"srd-2024_dart-plus-1","category":"weapon","damageDice":"1d4","properties":["Finesse","Thrown","Vex"]}'::jsonb)
