insert into item_catalog (id, data) values ('srd-2024_demon-breastplate', '{"h":2,"w":2,"icon":"fa-shield-halved","name":"Demon Breastplate","slot":"armor","tags":["armor","very-rare","attunement","armor:medium"],"attune":"Requires attunement","baseAc":14,"flavor":"While wearing this armor, you gain a +1 bonus to Armor Class, and you know Abyssal. In addition, the armor''s clawed gauntlets allow your Unarmed Strikes to deal 1d8 Slashing damage instead of the usual Bludgeoning damage, and you gain a +1 bonus to the attack and damage rolls of your Unarmed Strikes.\n\n**Curse.** Once you don this cursed armor, you can''t doff it unless you are targeted by a Remove Curse spell or similar magic. While wearing the armor, you have Disadvantage on attack rolls against demons and on saving throws against their spells and special abilities.","rarity":"very-rare","source":"srd","weight":20,"srd_key":"srd-2024_demon-breastplate","acAddDex":true,"acDexCap":2,"category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
