insert into item_catalog (id, data) values ('srd-2024_feed-per-day', '{"h":1,"w":1,"icon":"fa-cube","name":"Feed (per day)","tags":["misc","adventuring-gear","common"],"value":0.05,"flavor":"Daily feed for a mount.","rarity":"common","source":"srd","weight":10,"srd_key":"srd-2024_feed-per-day","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-bronze-griffon', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Bronze Griffon)","tags":["misc","wondrous-item","rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Bronze Griffon (Rare)._** This bronze statuette is of a griffon rampant. It can become a **Griffon** for up to 6 hours. Once it has been used, it can''t be used again until 5 days have passed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-bronze-griffon","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-ebony-fly', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Ebony Fly)","tags":["misc","wondrous-item","rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Ebony Fly (Rare)._** This ebony statuette, carved in the likeness of a horsefly, can become a **Giant Fly** (see the accompanying stat block) for up to 12 hours and can be ridden as a mount. Once it has been used, it can''t be used again until 2 days have passed.\n\n> #### **Giant Fly**\n> *Large Beast, Unaligned*\n> **AC** 11\n> **Initiative** +1 (11)\n> **HP** 15 (3d10 + 3)\n> **Speed** Speed 30 ft., Fly 60 ft.\n> |Attribute|Score|Mod|Save|\n> |---|---|---|---|\n> |Str|14|+2|+2|\n> |Dex|13|+1|+1|\n> |Con|13|+1|+1|\n> |Int|2|-4|-4|\n> |Wis|10|+0|+0|\n> |Cha|3|-4|-4|\n\n> **Senses** Darkvision 60 ft., Passive Perception 10\n> **Languages** None\n> **CR** 0 (XP 0; PB +2)","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-ebony-fly","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-golden-lions', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Golden Lions)","tags":["misc","wondrous-item","rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Golden Lions (Rare)._** These gold statuettes of lions are always created in pairs. You can use one figurine or both simultaneously. Each can become a **Lion** for up to 1 hour. Once a lion has been used, it can''t be used again until 7 days have passed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-golden-lions","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-ivory-goats', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Ivory Goats)","tags":["misc","wondrous-item","rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Golden Lions (Rare)._** These gold statuettes of lions are always created in pairs. You can use one figurine or both simultaneously. Each can become a **Lion** for up to 1 hour. Once a lion has been used, it can''t be used again until 7 days have passed.\n\n**Goat of Terror.** This figurine can become a **Giant Goat** for up to 3 hours. The goat can''t attack, but you can (harmlessly) remove its horns and use them as weapons. One horn becomes a *+1 Lance*, and the other becomes a *+2 Longsword*. Removing a horn requires a Magic action, and the weapons disappear and the horns return when the goat reverts to figurine form. While you ride the goat, any Hostile creature that starts its turn within a 30-foot Emanation originating from the goat must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute, until you are no longer riding the goat, or until the goat reverts to figurine form. The Frightened creature repeats the save at the end of each of its turns, ending the effect on itself on a success. Once it succeeds on the save, a creature is immune to this effect for the next 24 hours. Once the figurine has been used, it can''t be used again until 15 days have passed.\n\n**_Goat of Traveling._** This figurine can become a Large goat with the same statistics as a **Riding Horse**. It has 24 charges, and each hour or portion thereof it spends in goat form costs 1 charge. While it has charges, you can use it as often as you wish. When it runs out of charges, it reverts to a figurine and can''t be used again until 7 days have passed, when it regains all expended charges.\n\n**_Goat of Travail._** This figurine can become a **Giant Goat** for up to 3 hours. Once it has been used, it can''t be used again until 30 days have passed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-ivory-goats","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-marble-elephant', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Marble Elephant)","tags":["misc","wondrous-item","rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Marble Elephant (Rare)._** This marble statuette resembles a trumpeting elephant. It can become an **Elephant** for up to 24 hours. Once it has been used, it can''t be used again until 7 days have passed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-marble-elephant","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-obsidian-stead', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Obsidian Stead)","tags":["misc","wondrous-item","very-rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Obsidian Steed (Very Rare)._** This polished obsidian horse can become a **Nightmare** for up to 24 hours. The nightmare fights only to defend itself. Once it has been used, it can''t be used again until 5 days have passed.\n\nThe figurine has a 10 percent chance each time you use it to ignore your orders, including a command to revert to figurine form. If you mount the nightmare while it is ignoring your orders, you and the nightmare are instantly transported to a random location on the plane of Hades, where the nightmare reverts to figurine form.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-obsidian-stead","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-onyx-dog', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Onyx Dog)","tags":["misc","wondrous-item","rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Onyx Dog (Rare)._** This onyx statuette of a dog can become a **Mastiff** for up to 6 hours. The mastiff has an Intelligence of 8 and can speak Common. It also has Blindsight with a range of 60 feet. Once it has been used, it can''t be used again until 7 days have passed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-onyx-dog","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_figurine-of-wondrous-power-serpentine-owl', '{"h":1,"w":1,"icon":"fa-cube","name":"Figurine of Wondrous Power (Serpentine Owl)","tags":["misc","wondrous-item","rare"],"flavor":"A *Figurine of Wondrous Power* is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine''s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Serpentine Owl (Rare)._** This serpentine statuette of an owl can become a **Giant Owl** for up to 8 hours. The owl can communicate telepathically with you at any range if you and it are on the same plane of existence. Once it has been used, it can''t be used again until 2 days have passed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_figurine-of-wondrous-power-serpentine-owl","category":"misc"}'::jsonb)
