insert into item_catalog (id, data) values ('srd-2024_flame-tongue-battleaxe', '{"h":2,"w":1,"icon":"fa-khanda","name":"Flame Tongue Battleaxe","tags":["weapon","rare","slashing","topple","versatile","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"While holding this magic weapon, you can take a Bonus Action and use a command word to cause flames to engulf the damage-dealing part of the weapon. These flames shed Bright Light in a 40 foot radius and Dim Light for an additional 40 feet. While the weapon is ablaze, it deals an extra 2d6 Fire damage on a hit. The flames last until you take a Bonus Action to issue the command again or until you drop, stow, or sheathe the weapon.","rarity":"rare","source":"srd","weight":4,"srd_key":"srd-2024_flame-tongue-battleaxe","category":"weapon","damageDice":"1d8","properties":["Topple","Versatile"]}'::jsonb)
