  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_frost-brand-glaive', '{"h":3,"w":1,"icon":"fa-location-arrow","name":"Frost Brand (Glaive)","tags":["weapon","very-rare","slashing","graze","heavy","reach","two-handed","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you hit with an attack roll using this magic weapon, the target takes an extra 1d6 Cold damage. In addition, while you hold the weapon, you have Resistance to Fire damage. In freezing temperatures, the weapon sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet. When you draw this weapon, you can extinguish all nonmagical flames within 30 feet of yourself. Once used, this property can''t be used again for 1 hour.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_frost-brand-glaive","category":"weapon","damageDice":"1d10","properties":["Graze","Heavy","Reach","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
