insert into item_catalog (id, data) values ('srd-2024_gauntlets-of-ogre-power', '{"h":1,"w":1,"icon":"fa-mitten","name":"Gauntlets of Ogre Power","slot":"gloves","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"Your Strength is 19 while you wear these gauntlets. They have no effect on you if your Strength is 19 or higher without them.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_gauntlets-of-ogre-power","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_gem-of-brightness', '{"h":1,"w":1,"icon":"fa-gem","name":"Gem of Brightness","tags":["misc","wondrous-item","uncommon"],"flavor":"This prism has 50 charges. While you are holding it, you can take a Magic action and use one of three command words to cause one of the following effects: First Command Word. The gem sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. This effect doesn''t expend a charge. It lasts until you take a Bonus Action to repeat the command word or until you use another function of the gem. Second Command Word. You expend 1 charge and cause the gem to fire a brilliant beam of light at one creature you can see within 60 feet of yourself. The creature must succeed on a DC 15 Constitution saving throw or have the Blinded condition for 1 minute. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success. Third Command Word. You expend 5 charges and cause the gem to flare with intense light in a 30 foot Cone. Each creature in the Cone makes a saving throw as if struck by the beam created with the second command word. When all of the gem''s charges are expended, the gem becomes a nonmagical jewel worth 50 GP.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_gem-of-brightness","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_gem-of-seeing', '{"h":1,"w":1,"icon":"fa-gem","name":"Gem of Seeing","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires attunement","flavor":"This gem has 3 charges. As a Magic action, you can expend 1 charge. For the next 10 minutes, you have Truesight out to 120 feet when you peer through the gem. The gem regains 1d3 expended charges daily at dawn.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_gem-of-seeing","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
