insert into item_catalog (id, data) values ('srd-2024_glaive-of-life-stealing', '{"h":3,"w":1,"icon":"fa-location-arrow","name":"Glaive of Life Stealing","tags":["weapon","rare","slashing","graze","heavy","reach","two-handed","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn''t a Construct or an Undead, and you gain Temporary Hit Points equal to the amount of Necrotic damage taken.","rarity":"rare","source":"srd","weight":6,"srd_key":"srd-2024_glaive-of-life-stealing","category":"weapon","damageDice":"1d10","properties":["Graze","Heavy","Reach","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_glaive-of-sharpness', '{"h":3,"w":1,"icon":"fa-location-arrow","name":"Glaive of Sharpness","tags":["weapon","very-rare","slashing","graze","heavy","reach","two-handed","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target.\n\nWhen you attack a creature with this weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 14 Slashing damage and gains 1 Exhaustion level.","rarity":"very-rare","source":"srd","weight":6,"srd_key":"srd-2024_glaive-of-sharpness","category":"weapon","damageDice":"1d10","properties":["Graze","Heavy","Reach","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_glaive-of-wounding', '{"h":3,"w":1,"icon":"fa-location-arrow","name":"Glaive of Wounding","tags":["weapon","rare","slashing","graze","heavy","reach","two-handed","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour. The target repeats the save at the end of each of its turns, ending the effect on itself on a success.","rarity":"rare","source":"srd","weight":6,"srd_key":"srd-2024_glaive-of-wounding","category":"weapon","damageDice":"1d10","properties":["Graze","Heavy","Reach","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
