insert into item_catalog (id, data) values ('srd-2024_glamoured-studded-leather', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Glamoured Studded Leather","slot":"armor","tags":["armor","rare"],"flavor":"While wearing this armor, you gain a +1 bonus to Armor Class. You can also take a Bonus Action to cause the armor to assume the appearance of a normal set of clothing or some other kind of armor. You decide what it looks like—including color, style, and accessories—but the armor retains its normal bulk and weight. The illusory appearance lasts until you use this property again or doff the armor.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_glamoured-studded-leather","category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_glassblowers-tools', '{"h":1,"w":1,"icon":"fa-screwdriver-wrench","name":"Glassblower''s Tools (30 GP)","tags":["tool","tools","common"],"value":30,"flavor":"Ability: Intelligence. Utilize: Discern what a glass object held in the past 24 hours (DC 15). Craft: Glass Bottle, Magnifying Glass, Spyglass, Vial","rarity":"common","source":"srd","weight":5,"srd_key":"srd-2024_glassblowers-tools","category":"tool","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_gloves-of-missile-snaring', '{"h":1,"w":1,"icon":"fa-mitten","name":"Gloves of Missile Snaring","slot":"gloves","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"If you''re hit by an attack roll made with a Ranged or Thrown weapon while wearing these gloves, you can take a Reaction to reduce the damage by 1d10 plus your Dexterity modifier if you have a free hand. If you reduce the damage to 0, you can catch the ammunition or weapon if it is small enough for you to hold in that hand.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_gloves-of-missile-snaring","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_gloves-of-swimming-and-climbing', '{"h":1,"w":1,"icon":"fa-mitten","name":"Gloves of Swimming and Climbing","slot":"gloves","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While wearing these gloves, you have a Climb Speed and a Swim Speed equal to your Speed, and you gain a +5 bonus to Strength (Athletics) checks made to climb or swim.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_gloves-of-swimming-and-climbing","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_goggles-of-night', '{"h":1,"w":1,"icon":"fa-cube","name":"Goggles of Night","tags":["misc","wondrous-item","uncommon"],"flavor":"While wearing these dark lenses, you have Darkvision out to 60 feet. If you already have Darkvision, wearing the goggles increases its range by 60 feet.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_goggles-of-night","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_grappling-hook', '{"h":1,"w":1,"icon":"fa-cube","name":"Grappling Hook","tags":["misc","adventuring-gear","common"],"value":2,"flavor":"As a Utilize action, you can throw the Grappling Hook at a railing, a ledge, or another catch within 50 feet of yourself, and the hook catches on if you succeed on a DC 13 Dexterity (Acrobatics) check. If you tied a Rope to the hook, you can then climb it.","rarity":"common","source":"srd","weight":4,"srd_key":"srd-2024_grappling-hook","category":"misc","valueUnit":"gp"}'::jsonb)
