insert into item_catalog (id, data) values ('srd-2024_half-plate-armor-of-etherealness', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Half Plate Armor of Etherealness","slot":"armor","tags":["armor","legendary","attunement","armor:medium","stealth_disadvantage"],"attune":"Requires attunement","baseAc":15,"flavor":"While you''re wearing this armor, you can take a Magic action and use a command word to gain the effect of the Etherealness spell. The spell ends immediately if you remove the armor or take a Magic action to repeat the command word. This property of the armor can''t be used again until the next dawn.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_half-plate-armor-of-etherealness","acAddDex":true,"acDexCap":2,"category":"armor"}'::jsonb)
