insert into item_catalog (id, data) values ('srd-2024_headband-of-intellect', '{"h":1,"w":1,"icon":"fa-hat-wizard","name":"Headband of Intellect","slot":"helmet","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"Your Intelligence is 19 while you wear this headband. It has no effect on you if your Intelligence is 19 or higher without it.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_headband-of-intellect","category":"misc"}'::jsonb)
