insert into item_catalog (id, data) values ('srd-2024_holy-avenger', '{"h":1,"w":1,"icon":"fa-khanda","name":"Holy Avenger","tags":["weapon","legendary","attunement"],"attune":"Requires Attunement by a Paladin","flavor":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Fiend or an Undead with it, that creature takes an extra 2d10 Radiant damage. While you hold the drawn weapon, it creates a 10-foot Emanation originating from you. You and all creatures Friendly to you in the Emanation have Advantage on saving throws against spells and other magical effects. If you have 17 or more levels in the Paladin class, the size of the Emanation increases to 30 feet.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_holy-avenger","category":"weapon"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
