insert into item_catalog (id, data) values ('srd-2024_holy-symbol-amulet', '{"h":1,"w":1,"icon":"fa-gem","name":"Holy Symbol, Amulet","slot":"neck","tags":["misc","adventuring-gear","common"],"value":5,"flavor":"A Holy Symbol Amulet is bejeweled or painted to channel divine magic. A Cleric or Paladin can use it as a Spellcasting Focus. It can be worn around the neck or held in hand.","rarity":"common","source":"srd","weight":1,"srd_key":"srd-2024_holy-symbol-amulet","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_holy-symbol-emblem', '{"h":1,"w":1,"icon":"fa-cube","name":"Holy Symbol, Emblem","tags":["misc","adventuring-gear","common"],"value":5,"flavor":"A Holy Symbol Emblem is bejeweled or painted to channel divine magic. A Cleric or Paladin can use it as a Spellcasting Focus. It must be borne on fabric (such as a tabard or banner) or a Shield.","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_holy-symbol-emblem","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
