insert into item_catalog (id, data) values ('srd-2024_longsword-of-life-stealing', '{"h":2,"w":1,"icon":"fa-khanda","name":"Longsword of Life Stealing","tags":["weapon","rare","slashing","sap","versatile","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn''t a Construct or an Undead, and you gain Temporary Hit Points equal to the amount of Necrotic damage taken.","rarity":"rare","source":"srd","weight":3,"srd_key":"srd-2024_longsword-of-life-stealing","category":"weapon","damageDice":"1d8","properties":["Sap","Versatile"]}'::jsonb)
