insert into item_catalog (id, data) values ('srd-2024_longsword-of-sharpness', '{"h":2,"w":1,"icon":"fa-khanda","name":"Longsword of Sharpness","tags":["weapon","very-rare","slashing","sap","versatile","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target.\n\nWhen you attack a creature with this weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 14 Slashing damage and gains 1 Exhaustion level.","rarity":"very-rare","source":"srd","weight":3,"srd_key":"srd-2024_longsword-of-sharpness","category":"weapon","damageDice":"1d8","properties":["Sap","Versatile"]}'::jsonb)
