insert into item_catalog (id, data) values ('srd-2024_longsword-of-wounding', '{"h":2,"w":1,"icon":"fa-khanda","name":"Longsword of Wounding","tags":["weapon","rare","slashing","sap","versatile","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour. The target repeats the save at the end of each of its turns, ending the effect on itself on a success.","rarity":"rare","source":"srd","weight":3,"srd_key":"srd-2024_longsword-of-wounding","category":"weapon","damageDice":"1d8","properties":["Sap","Versatile"]}'::jsonb)
