insert into item_catalog (id, data) values ('srd-2024_medallion-of-thoughts', '{"h":1,"w":1,"icon":"fa-gem","name":"Medallion of Thoughts","slot":"neck","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"The medallion has 5 charges. While wearing it, you can expend 1 charge to cast Detect Thoughts (save DC 13) from it. The medallion regains 1d4 expended charges daily at dawn.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_medallion-of-thoughts","category":"misc"}'::jsonb)
