insert into item_catalog (id, data) values ('srd-2024_necklace-of-adaptation', '{"h":1,"w":1,"icon":"fa-gem","name":"Necklace of Adaptation","slot":"neck","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While wearing this necklace, you can breathe normally in any environment, and you have Advantage on saving throws made to avoid or end the Poisoned condition.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_necklace-of-adaptation","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_necklace-of-fireballs', '{"h":1,"w":1,"icon":"fa-gem","name":"Necklace of Fireballs","slot":"neck","tags":["misc","wondrous-item","rare"],"flavor":"This necklace has 1d6 + 3 beads hanging from it. You can take a Magic action to detach a bead and throw it up to 60 feet away. When it reaches the end of its trajectory, the bead detonates as a level 3 Fireball (save DC 15). You can hurl multiple beads, or even the whole necklace, at one time. When you do so, increase the damage of the Fireball by 1d6 for each bead after the first (maximum 12d6).","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_necklace-of-fireballs","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_necklace-of-prayer-beads', '{"h":1,"w":1,"icon":"fa-gem","name":"Necklace of Prayer Beads","slot":"neck","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires Attunement by a Cleric, Druid, or Paladin","flavor":"This necklace has 1d4 + 2 magic beads made from aquamarine, black pearl, or topaz. It also has many nonmagical beads made from stones such as amber, bloodstone, citrine, coral, jade, pearl, or quartz. If a magic bead is removed from the necklace, that bead loses its magic.\n\nSix types of magic beads exist. The GM decides the type of each bead on the necklace or determines it randomly by rolling on the table below. A necklace can have more than one bead of the same type. To use one, you must be wearing the necklace. Each bead contains a spell that you can cast from it as a Bonus Action (using your spell save DC if a save is necessary). Once a magic bead''s spell is cast, that bead can''t be used again until the next dawn.\n\n| 1d20  | Bead                 | Spell                         |\n|-------|----------------------|-------------------------------|\n| 1–6   | Bead of Blessing     | Bless                         |\n| 7–12  | Bead of Curing       | Cure Wounds (level 2 version) |\n| 13–16 | Bead of Favor        | Greater Restoration           |\n| 17–18 | Bead of Smiting      | Shining Smite                 |\n| 19    | Bead of Summons      | Guardian of Faith             |\n| 20    | Bead of Wind Walking | Wind Walk                     |","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_necklace-of-prayer-beads","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_needles-50', '{"h":1,"w":1,"icon":"fa-location-arrow","name":"Needles (50)","tags":["ammo","ammunition","common"],"value":1,"flavor":"Ammunition for weapons that use needles. Comes in a pack of 50. Typically stored in a pouch.","rarity":"common","source":"srd","weight":1,"srd_key":"srd-2024_needles-50","category":"ammo","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_net', '{"h":2,"w":1,"icon":"fa-khanda","name":"Net","tags":["weapon","common"],"value":1,"flavor":"When you take the Attack action, you can replace one of your attacks with throwing a Net. Target a creature you can see within 15 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or have the Restrained condition until it escapes. The target succeeds automatically if it is Huge or larger. To escape, the target or a creature within 5 feet of it must take an action to make a DC 10 Strength (Athletics) check, freeing the Restrained creature on a success. Destroying the Net (AC 10; 5 HP; Immunity to Bludgeoning, Poison, and Psychic damage) also frees the target, ending the effect.","rarity":"common","source":"srd","weight":3,"srd_key":"srd-2024_net","category":"weapon","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_nine-lives-stealer-battleaxe', '{"h":2,"w":1,"icon":"fa-khanda","name":"Nine Lives Stealer (Battleaxe)","tags":["weapon","very-rare","slashing","topple","versatile","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon.\n\n**Life Stealing.** The weapon has 1d8 + 1 charges. When you attack a creature that has fewer than 100 Hit Points with this weapon and roll a 20 on the d20 for the attack roll, the creature must succeed on a DC 15 Constitution saving throw or be slain instantly as the sword tears its life force from its body. Constructs and Undead succeed on the save automatically. The weapon loses 1 charge if the creature is slain. When the weapon has no charges remaining, it loses this property.","rarity":"very-rare","source":"srd","weight":4,"srd_key":"srd-2024_nine-lives-stealer-battleaxe","category":"weapon","damageDice":"1d8","properties":["Topple","Versatile"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
