insert into item_catalog (id, data) values ('srd-2024_nine-lives-stealer-whip', '{"h":2,"w":1,"icon":"fa-khanda","name":"Nine Lives Stealer (Whip)","tags":["weapon","very-rare","slashing","finesse","reach","slow","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon.\n\n**Life Stealing.** The weapon has 1d8 + 1 charges. When you attack a creature that has fewer than 100 Hit Points with this weapon and roll a 20 on the d20 for the attack roll, the creature must succeed on a DC 15 Constitution saving throw or be slain instantly as the sword tears its life force from its body. Constructs and Undead succeed on the save automatically. The weapon loses 1 charge if the creature is slain. When the weapon has no charges remaining, it loses this property.","rarity":"very-rare","source":"srd","weight":3,"ability":"finesse","srd_key":"srd-2024_nine-lives-stealer-whip","category":"weapon","damageDice":"1d4","properties":["Finesse","Reach","Slow"]}'::jsonb)
