insert into item_catalog (id, data) values ('srd-2024_oathbow-longbow', '{"h":3,"w":1,"icon":"fa-khanda","name":"Oathbow (Longbow)","tags":["weapon","very-rare","piercing","ammunition","heavy","slow","two-handed","attunement"],"type":"Piercing","attune":"Requires attunement","flavor":"When you nock an arrow on this bow, it whispers in Elvish, \"Swift defeat to my enemies.\" When you use this weapon to make a ranged attack, you can utter or sign the following command words: \"Swift death to you who have wronged me.\" The target of your attack becomes your sworn enemy until it dies or until dawn 7 days later. You can have only one such sworn enemy at a time. When your sworn enemy dies, you can choose a new one after the next dawn. When you make a ranged attack roll with this weapon against your sworn enemy, you have Advantage on the roll. In addition, your target gains no benefit from Half Cover or Three-Quarters Cover, and you suffer no Disadvantage due to long range. If the attack hits, your sworn enemy takes an extra 3d6 Piercing damage. While your sworn enemy lives, you have Disadvantage on attack rolls with all other weapons.","ranged":true,"rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_oathbow-longbow","category":"weapon","damageDice":"1d8","properties":["Ammunition","Heavy","Slow","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_oathbow-shortbow', '{"h":3,"w":1,"icon":"fa-khanda","name":"Oathbow (Shortbow)","tags":["weapon","very-rare","piercing","ammunition","two-handed","vex","attunement"],"type":"Piercing","attune":"Requires attunement","flavor":"When you nock an arrow on this bow, it whispers in Elvish, \"Swift defeat to my enemies.\" When you use this weapon to make a ranged attack, you can utter or sign the following command words: \"Swift death to you who have wronged me.\" The target of your attack becomes your sworn enemy until it dies or until dawn 7 days later. You can have only one such sworn enemy at a time. When your sworn enemy dies, you can choose a new one after the next dawn. When you make a ranged attack roll with this weapon against your sworn enemy, you have Advantage on the roll. In addition, your target gains no benefit from Half Cover or Three-Quarters Cover, and you suffer no Disadvantage due to long range. If the attack hits, your sworn enemy takes an extra 3d6 Piercing damage. While your sworn enemy lives, you have Disadvantage on attack rolls with all other weapons.","ranged":true,"rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_oathbow-shortbow","category":"weapon","damageDice":"1d6","properties":["Ammunition","Two-Handed","Vex"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_oil', '{"h":1,"w":1,"icon":"fa-flask","name":"Oil","tags":["weapon","common"],"value":0.1,"flavor":"You can douse a creature, object, or space with Oil or use it as fuel, as detailed below. Dousing a Creature or an Object. When you take the Attack action, you can replace one of your attacks with throwing an Oil flask. Target one creature or object within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or be covered in oil. If the target takes Fire damage before the oil dries (after 1 minute), the target takes an extra 5 Fire damage from burning oil. Dousing a Space. You can take the Utilize action to pour an Oil flask on level ground to cover a 5-foot-square area within 5 feet of yourself. If lit, the oil burns until the end of the turn 2 rounds from when the oil was lit (or 12 seconds) and deals 5 Fire damage to any creature that enters the area or ends its turn there. A creature can take this damage only once per turn. Fuel. Oil serves as fuel for Lamps and Lanterns. Once lit, a flask of Oil burns for 6 hours in a Lamp or Lantern. That duration doesn''t need to be consecutive; you can extinguish the burning Oil (as a Utilize action) and rekindle it again until it has burned for a total of 6 hours.","rarity":"common","source":"srd","weight":1,"srd_key":"srd-2024_oil","category":"weapon","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_oil-of-etherealness', '{"h":1,"w":1,"icon":"fa-flask","name":"Oil of Etherealness","tags":["consumable","potion","rare"],"flavor":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it''s wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of the Etherealness spell for 1 hour. Beads of this cloudy, gray oil form on the outside of its container and quickly evaporate.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_oil-of-etherealness","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_oil-of-sharpness', '{"h":1,"w":1,"icon":"fa-flask","name":"Oil of Sharpness","tags":["consumable","potion","very-rare"],"flavor":"One vial of this oil can coat one Melee weapon or twenty pieces of ammunition, but only ammunition and Melee weapons that are nonmagical and deal Slashing or Piercing damage are affected. Applying the oil takes 1 minute, after which the oil magically seeps into whatever it coats, turning the coated weapon into a +3 Weapon or the coated ammunition into +3 Ammunition. This clear, gelatinous oil sparkles with tiny, ultrathin silver shards.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_oil-of-sharpness","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_oil-of-slipperiness', '{"h":1,"w":1,"icon":"fa-flask","name":"Oil of Slipperiness","tags":["consumable","potion","uncommon"],"flavor":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it''s wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of the Freedom of Movement spell for 8 hours. Alternatively, the oil can be poured on the ground as a Magic action, where it covers a 10-foot square, duplicating the effect of the Grease spell in that area for 8 hours. This sticky, black unguent is thick and heavy, but it flows quickly when poured.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_oil-of-slipperiness","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_padded-armor', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Padded Armor","slot":"armor","tags":["armor","common","armor:light","stealth_disadvantage"],"value":5,"baseAc":11,"flavor":"A padded armor.","rarity":"common","source":"srd","weight":8,"srd_key":"srd-2024_padded-armor","acAddDex":true,"category":"armor","valueUnit":"gp"}'::jsonb)
