insert into item_catalog (id, data) values ('srd-2024_pearl-of-power', '{"h":1,"w":1,"icon":"fa-gem","name":"Pearl of Power","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires Attunement by a Spellcaster","flavor":"While this pearl is on your person, you can take a Magic action to regain one expended spell slot of level 3 or lower. Once you use the pearl, it can''t be used again until the next dawn.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_pearl-of-power","category":"misc"}'::jsonb)
