insert into item_catalog (id, data) values ('srd-2024_periapt-of-health', '{"h":1,"w":1,"icon":"fa-gem","name":"Periapt of Health","slot":"neck","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While wearing this pendant, you can take a Magic action to regain 2d4 + 2 Hit Points. Once used, this property can''t be used again until the next dawn. In addition, you have Advantage on saving throws to avoid or end the Poisoned condition while you wear this pendant.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_periapt-of-health","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_periapt-of-proof-against-poison', '{"h":1,"w":1,"icon":"fa-gem","name":"Periapt of Proof against Poison","slot":"neck","tags":["misc","wondrous-item","rare","attunement"],"attune":"Requires attunement","flavor":"This delicate silver chain has a brilliant-cut black gem pendant. While you wear it, you have Immunity to the Poisoned condition and Poison damage.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_periapt-of-proof-against-poison","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_periapt-of-wound-closure', '{"h":1,"w":1,"icon":"fa-gem","name":"Periapt of Wound Closure","slot":"neck","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While wearing this pendant, you gain the following benefits. Life Preservation. Whenever you make a Death Saving Throw, you can change a roll of 9 or lower to a 10, turning a failed save into a successful one. Natural Healing Boost. Whenever you roll a Hit Point Die to regain Hit Points, double the number of Hit Points it restores.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_periapt-of-wound-closure","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
