insert into item_catalog (id, data) values ('srd-2024_poison-basic', '{"h":1,"w":1,"icon":"fa-cube","name":"Poison, Basic","tags":["misc","adventuring-gear","common"],"value":100,"flavor":"As a Bonus Action, you can use a vial of Basic Poison to coat one weapon or up to three pieces of ammunition. A creature that takes Piercing or Slashing damage from the poisoned weapon or ammunition takes an extra 1d4 Poison damage. Once applied, the poison retains potency for 1 minute or until its damage is dealt, whichever comes first.","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_poison-basic","category":"misc","valueUnit":"gp"}'::jsonb)
