insert into item_catalog (id, data) values ('srd-2024_pole', '{"h":1,"w":1,"icon":"fa-cube","name":"Pole","tags":["misc","adventuring-gear","common"],"value":0.05,"flavor":"A Pole is 10 feet long. You can use it to touch something up to 10 feet away. If you must make a Strength (Athletics) check as part of a High or Long Jump, you can use the Pole to vault, giving yourself Advantage on the check.","rarity":"common","source":"srd","weight":7,"srd_key":"srd-2024_pole","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_portable-hole', '{"h":1,"w":1,"icon":"fa-cube","name":"Portable Hole","tags":["misc","wondrous-item","rare"],"flavor":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter. You can take a Magic action to unfold a Portable Hole and place it on or against a solid surface, whereupon the Portable Hole creates an extradimensional hole 10 feet deep. The cylindrical space within the hole exists on a different plane of existence, so it can''t be used to create open passages. Any creature inside an open Portable Hole can exit the hole by climbing out of it. You can take a Magic action to close a Portable Hole by taking hold of the edges of the cloth and folding it up. Folding the cloth closes the hole, and any creatures or objects within remain in the extradimensional space. No matter what''s in it, the hole weighs next to nothing. If the hole is folded up, a creature within the hole''s extradimensional space can take an action to make a DC 10 Strength (Athletics) check. On a successful check, the creature forces its way out and appears within 5 feet of the Portable Hole. A closed Portable Hole holds enough air for 1 hour of breathing, divided by the number of breathing creatures inside. Placing a Portable Hole inside an extradimensional space created by a Bag of Holding, Handy Haversack, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate and not behind Total Cover is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can''t be reopened.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_portable-hole","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_pot-iron', '{"h":1,"w":1,"icon":"fa-cube","name":"Pot, Iron","tags":["misc","adventuring-gear","common"],"value":2,"flavor":"An Iron Pot holds up to 1 gallon.","rarity":"common","source":"srd","weight":10,"srd_key":"srd-2024_pot-iron","category":"misc","valueUnit":"gp"}'::jsonb)
