insert into item_catalog (id, data) values ('srd-2024_potion-of-animal-friendship', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Animal Friendship","tags":["consumable","potion","uncommon"],"flavor":"When you drink this potion, you can cast the level 3 version of the Animal Friendship spell (save DC 13). Agitating this potion''s muddy liquid brings little bits into view: a fish scale, a hummingbird feather, a cat claw, or a squirrel hair.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-animal-friendship","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_potion-of-clairvoyance', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Clairvoyance","tags":["consumable","potion","rare"],"flavor":"When you drink this potion, you gain the effect of the Clairvoyance spell (no Concentration required). An eyeball bobs in this potion''s yellowish liquid but vanishes when the potion is opened.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-clairvoyance","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_potion-of-climbing', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Climbing","tags":["consumable","potion","common"],"flavor":"When you drink this potion, you gain a Climb Speed equal to your Speed for 1 hour. During this time, you have Advantage on Strength (Athletics) checks to climb. This potion is separated into brown, silver, and gray layers resembling bands of stone. Shaking the bottle fails to mix the colors.","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-climbing","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_potion-of-diminution', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Diminution","tags":["consumable","potion","rare"],"flavor":"When you drink this potion, you gain the \"reduce\" effect of the Enlarge/Reduce spell for 1d4 hours (no Concentration required). The red in the potion''s liquid continuously contracts to a tiny bead and then expands to color the clear liquid around it. Shaking the bottle fails to interrupt this process.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-diminution","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_potion-of-flying', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Flying","tags":["consumable","potion","very-rare"],"flavor":"When you drink this potion, you gain a Fly Speed equal to your Speed for 1 hour and can hover. If you''re in the air when the potion wears off, you fall unless you have some other means of staying aloft. This potion''s clear liquid floats at the top of its container and has cloudy white impurities drifting in it.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-flying","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
