  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_potion-of-giant-strength', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Giant Strength","tags":["consumable","potion","common"],"flavor":"When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score (see the table below). The potion has no effect on you if your Strength is equal to or greater than that score.\n\nThis potion''s transparent liquid has floating in it a sliver of light resembling a giant''s fingernail.\n\n| Potion                                    | Str. | Rarity    |\n|-------------------------------------------|------|-----------|\n| Potion of Giant Strength (hill)           | 21   | Uncommon  |\n| Potion of Giant Strength (frost or stone) | 23   | Rare      |\n| Potion of Giant Strength (fire)           | 25   | Rare      |\n| Potion of Giant Strength (cloud)          | 27   | Very Rare |\n| Potion of Giant Strength (storm)          | 29   | Legendary |","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-giant-strength","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_potion-of-growth', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Growth","tags":["consumable","potion","uncommon"],"flavor":"When you drink this potion, you gain the \"enlarge\" effect of the Enlarge/Reduce spell for 10 minutes (no Concentration required). The red in the potion''s liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts. Shaking the bottle fails to interrupt this process.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-growth","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
