insert into item_catalog (id, data) values ('srd-2024_potion-of-heroism', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Heroism","tags":["consumable","potion","rare"],"flavor":"When you drink this potion, you gain 10 Temporary Hit Points that last for 1 hour. For the same duration, you are under the effect of the Bless spell (no Concentration required). This potion''s blue liquid bubbles and steams as if boiling.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-heroism","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_potion-of-invisibility', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Invisibility","tags":["consumable","potion","rare"],"flavor":"This potion''s container looks empty but feels as though it holds liquid. When you drink the potion, you have the Invisible condition for 1 hour. The effect ends early if you make an attack roll, deal damage, or cast a spell.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-invisibility","category":"consumable"}'::jsonb)
