insert into item_catalog (id, data) values ('srd-2024_potion-of-poison', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Poison","tags":["consumable","potion","uncommon"],"flavor":"This concoction looks, smells, and tastes like a Potion of Healing or another beneficial potion. However, it is actually poison masked by illusion magic. Identify reveals its true nature. If you drink this potion, you take 4d6 Poison damage and must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 hour.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-poison","category":"consumable"}'::jsonb)
