insert into item_catalog (id, data) values ('srd-2024_potion-of-resistance', '{"h":1,"w":1,"icon":"fa-flask","name":"Potion of Resistance","tags":["consumable","potion","uncommon"],"flavor":"When you drink this potion, you have Resistance to one type of damage for 1 hour. The GM chooses the type or determines it randomly by rolling on the following table.\n\n| 1d10 | Damage Type |\n|------|-------------|\n| 1    | Acid        |\n| 2    | Cold        |\n| 3    | Fire        |\n| 4    | Force       |\n| 5    | Lightning   |\n| 6    | Necrotic    |\n| 7    | Poison      |\n| 8    | Psychic     |\n| 9    | Radiant     |\n| 10   | Thunder     |","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_potion-of-resistance","category":"consumable"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
