insert into item_catalog (id, data) values ('srd-2024_potions-of-healing', '{"h":1,"w":1,"icon":"fa-flask","name":"Potions of Healing","tags":["consumable","potion","common"],"flavor":"You regain Hit Points when you drink this potion. The number of Hit Points depends on the potion''s rarity, as shown in the table below.\n\nWhatever its potency, the potion''s red liquid glimmers when agitated.\n\n| Potion                       | HP Regained | Rarity    |\n|------------------------------|-------------|-----------|\n| Potion of Healing            | 2d4 + 2     | Common    |\n| Potion of Healing (greater)  | 4d4 + 4     | Uncommon  |\n| Potion of Healing (superior) | 8d4 + 8     | Rare      |\n| Potion of Healing (supreme)  | 10d4 + 20   | Very Rare |","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_potions-of-healing","category":"consumable"}'::jsonb)
