insert into item_catalog (id, data) values ('srd-2024_scarab-of-protection', '{"h":1,"w":1,"icon":"fa-gem","name":"Scarab of Protection","slot":"neck","tags":["misc","wondrous-item","legendary","attunement"],"attune":"Requires attunement","flavor":"This beetle-shaped medallion provides three benefits while it is on your person. Defense. You gain a +1 bonus to Armor Class. Preservation. The scarab has 12 charges. If you fail a saving throw against a Necromancy spell or a harmful effect originating from an Undead, you can take a Reaction to expend 1 charge and turn the failed save into a successful one. The scarab crumbles into powder and is destroyed when its last charge is expended. Spell Resistance. You have Advantage on saving throws against spells.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_scarab-of-protection","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_scholars-pack', '{"h":2,"w":2,"icon":"fa-screwdriver-wrench","name":"Scholar''s Pack","tags":["tool","equipment-pack","common"],"value":40,"flavor":"A Scholar''s Pack contains the following items: Backpack, Book, Ink, Ink Pen, Lamp, 10 flasks of Oil, 10 sheets of Parchment, and Tinderbox.","rarity":"common","source":"srd","weight":22,"srd_key":"srd-2024_scholars-pack","category":"tool","valueUnit":"gp"}'::jsonb)
