insert into item_catalog (id, data) values ('srd-2024_scimitar-of-life-stealing', '{"h":1,"w":1,"icon":"fa-khanda","name":"Scimitar of Life Stealing","tags":["weapon","rare","slashing","finesse","light","nick","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn''t a Construct or an Undead, and you gain Temporary Hit Points equal to the amount of Necrotic damage taken.","rarity":"rare","source":"srd","weight":3,"ability":"finesse","srd_key":"srd-2024_scimitar-of-life-stealing","category":"weapon","damageDice":"1d6","properties":["Finesse","Light","Nick"]}'::jsonb)
