insert into item_catalog (id, data) values ('srd-2024_scimitar-of-sharpness', '{"h":1,"w":1,"icon":"fa-khanda","name":"Scimitar of Sharpness","tags":["weapon","very-rare","slashing","finesse","light","nick","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target.\n\nWhen you attack a creature with this weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 14 Slashing damage and gains 1 Exhaustion level.","rarity":"very-rare","source":"srd","weight":3,"ability":"finesse","srd_key":"srd-2024_scimitar-of-sharpness","category":"weapon","damageDice":"1d6","properties":["Finesse","Light","Nick"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_scimitar-of-speed', '{"h":1,"w":1,"icon":"fa-khanda","name":"Scimitar of Speed","tags":["weapon","very-rare","attunement"],"attune":"Requires attunement","flavor":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. In addition, you can make one attack with it as a Bonus Action on each of your turns.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_scimitar-of-speed","category":"weapon"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_scimitar-of-wounding', '{"h":1,"w":1,"icon":"fa-khanda","name":"Scimitar of Wounding","tags":["weapon","rare","slashing","finesse","light","nick","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour. The target repeats the save at the end of each of its turns, ending the effect on itself on a success.","rarity":"rare","source":"srd","weight":3,"ability":"finesse","srd_key":"srd-2024_scimitar-of-wounding","category":"weapon","damageDice":"1d6","properties":["Finesse","Light","Nick"]}'::jsonb)
