insert into item_catalog (id, data) values ('srd-2024_slippers-of-spider-climbing', '{"h":1,"w":1,"icon":"fa-shoe-prints","name":"Slippers of Spider Climbing","slot":"boots","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While you wear these light shoes, you can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free. You have a Climb Speed equal to your Speed. However, the slippers don''t allow you to move this way on a slippery surface, such as one covered by ice or oil.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_slippers-of-spider-climbing","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
