  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_sovereign-glue', '{"h":1,"w":1,"icon":"fa-cube","name":"Sovereign Glue","tags":["misc","wondrous-item","legendary"],"flavor":"This viscous, milky-white substance can form a permanent adhesive bond between any two objects. It must be stored in a jar or flask that has been coated inside with Oil of Slipperiness. When found, a container contains 1d6 + 1 ounces. One ounce of the glue can cover a 1-foot square surface. Applying an ounce of Sovereign Glue takes a Utilize action, and the applied glue takes 1 minute to set. Once it has done so, the bond it creates can be broken only by the application of Universal Solvent or Oil of Etherealness, or with a Wish spell.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_sovereign-glue","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
