insert into item_catalog (id, data) values ('srd-2024_spell-scroll', '{"h":1,"w":1,"icon":"fa-scroll","name":"Spell Scroll","tags":["consumable","scroll","common"],"value":30,"flavor":"A Spell Scroll (Cantrip) or Spell Scroll (Level 1) is a magic item that bears the words of a cantrip or level 1 spell, respectively, determined by the scroll''s creator. If the spell is on your class''s spell list, you can read the scroll and cast the spell using its normal casting time and without providing any Material components. If the spell requires a saving throw or an attack roll, the spell save DC is 13, and the attack bonus is +5. The scroll disintegrates when the casting is completed.","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_spell-scroll","category":"consumable","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_spellguard-shield', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Spellguard Shield","slot":"armor","tags":["armor","very-rare","attunement"],"attune":"Requires attunement","flavor":"While holding this Shield, you have Advantage on saving throws against spells and other magical effects, and spell attack rolls have Disadvantage against you.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_spellguard-shield","category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_sphere-of-annihilation', '{"h":1,"w":1,"icon":"fa-cube","name":"Sphere of Annihilation","tags":["misc","wondrous-item","legendary"],"flavor":"This 2-foot-diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it.\n\nThe sphere obliterates all matter it passes through and all matter that passes through it. Artifacts are the exception. Unless an Artifact is susceptible to damage from a *Sphere of Annihilation*, it passes through the sphere unscathed. Anything else that touches the sphere but isn''t wholly engulfed and obliterated by it takes 8d10 Force damage.\n\n**_Controlling the Sphere._** A *Sphere of Annihilation* is stationary until someone takes control of it. If you are within 60 feet of a sphere, you can take a Magic action to make a DC 25 Intelligence (Arcana) check. On a successful check, you control the sphere until the start of your next turn, and if it was under another creature''s control, that creature loses control of the sphere. On a failed check, the sphere moves 10 feet toward you in a straight line.\n\nWhile in control of the sphere, you can take a Bonus Action to cause it to move in one direction of your choice, up to a number of feet equal to 5 times your Intelligence modifier (minimum 5 feet). Any creature whose space the sphere enters must succeed on a DC 19 Dexterity saving throw or be touched by it, taking 8d10 Force damage. A creature reduced to 0 Hit Points by this damage is obliterated, leaving its possessions behind but no other physical remains.\n\n**_Sphere Interactions._** If the sphere comes into contact with a planar portal (such as that created by the *Gate* spell) or an extradimensional space (such as that within a *Portable Hole*), the GM determines randomly what happens using the following table.\n\n| 1d100 | Result                                                                                                                     |\n|-------|----------------------------------------------------------------------------------------------------------------------------|\n| 01–50 | The sphere is destroyed.                                                                                                   |\n| 51–85 | The sphere moves through the portal or into the extradimensional space.                                                    |\n| 86–00 | A spatial rift sends the sphere and each creature and object within 180 feet of the sphere to a random plane of existence. |","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_sphere-of-annihilation","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_spikes-iron', '{"h":1,"w":1,"icon":"fa-location-arrow","name":"Spikes, Iron","tags":["misc","adventuring-gear","common"],"value":1,"flavor":"Iron Spikes come in bundles of ten. As a Utilize action, you can use a blunt object, such as a Light Hammer, to hammer a spike into wood, earth, or a similar material. You can do so to jam a door shut or to then tie a Rope or Chain to the Spike.","rarity":"common","source":"srd","weight":5,"srd_key":"srd-2024_spikes-iron","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_splint-armor', '{"h":3,"w":2,"icon":"fa-shield-halved","name":"Splint Armor","slot":"armor","tags":["armor","common","armor:heavy","stealth_disadvantage","str_req:15"],"value":200,"baseAc":17,"flavor":"A splint armor.","rarity":"common","source":"srd","weight":60,"srd_key":"srd-2024_splint-armor","category":"armor","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_splint-armor-plus-1', '{"h":3,"w":2,"icon":"fa-shield-halved","name":"Splint Armor (+1)","slot":"armor","tags":["armor","uncommon","magic+1","armor:heavy","stealth_disadvantage","str_req:15"],"baseAc":17,"flavor":"You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity.","rarity":"uncommon","source":"srd","weight":60,"effects":{"ac":1},"srd_key":"srd-2024_splint-armor-plus-1","category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_splint-armor-plus-2', '{"h":3,"w":2,"icon":"fa-shield-halved","name":"Splint Armor (+2)","slot":"armor","tags":["armor","rare","magic+2","armor:heavy","stealth_disadvantage","str_req:15"],"baseAc":17,"flavor":"You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity.","rarity":"rare","source":"srd","weight":60,"effects":{"ac":2},"srd_key":"srd-2024_splint-armor-plus-2","category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_splint-armor-plus-3', '{"h":3,"w":2,"icon":"fa-shield-halved","name":"Splint Armor (+3)","slot":"armor","tags":["armor","very-rare","magic+3","armor:heavy","stealth_disadvantage","str_req:15"],"baseAc":17,"flavor":"You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity.","rarity":"very-rare","source":"srd","weight":60,"effects":{"ac":3},"srd_key":"srd-2024_splint-armor-plus-3","category":"armor"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_spyglass', '{"h":1,"w":1,"icon":"fa-cube","name":"Spyglass","tags":["misc","adventuring-gear","common"],"value":1000,"flavor":"Objects viewed through a Spyglass are magnified to twice their size.","rarity":"common","source":"srd","weight":1,"srd_key":"srd-2024_spyglass","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-charming', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Charming","tags":["misc","staff","rare","attunement"],"attune":"Requires Attunement by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard","flavor":"This staff has 10 charges. While holding the staff, you can use any of its properties: Cast Spell. You can expend 1 of the staff''s charges to cast Charm Person, Command, or Comprehend Languages from it using your spell save DC. Reflect Enchantment.* If you succeed on a saving throw against an Enchantment spell that targets only you, you can take a Reaction to expend 1 charge from the staff and turn the spell back on its caster as if you had cast the spell. Resist Enchantment. If you fail a saving throw against an Enchantment spell that targets only you, you can turn your failed save into a successful one. You can''t use this property of the staff again until the next dawn. Regaining Charges. The staff regains 1d8 + 2 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff crumbles to dust and is destroyed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-charming","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-fire', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Fire","tags":["misc","staff","very-rare","attunement"],"attune":"Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard","flavor":"You have Resistance to Fire damage while you hold this staff.\n\n**_Spells._** The staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell         | Charge Cost |\n|---------------|-------------|\n| Burning Hands | 1           |\n| Fireball      | 3           |\n| Wall of Fire  | 4           |\n\n**_Regaining Charges._** The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff crumbles into cinders and is destroyed.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-fire","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-frost', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Frost","tags":["misc","staff","very-rare","attunement"],"attune":"Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard","flavor":"You have Resistance to Cold damage while you hold this staff.\n\n**_Spells._** The staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell        | Charge Cost |\n|--------------|-------------|\n| Cone of Cold | 5           |\n| Fog Cloud    | 1           |\n| Ice Storm    | 4           |\n| Wall of Ice  | 4           |\n\n**_Regaining Charges._** The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff turns to water and is destroyed.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-frost","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-healing', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Healing","tags":["misc","staff","rare","attunement"],"attune":"Requires Attunement by a Bard, Cleric, or Druid","flavor":"This staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spellcasting ability modifier. The table indicates how many charges you must expend to cast the spell.\n\n| Spell              | Charge Cost                                              |\n|--------------------|----------------------------------------------------------|\n| Cure Wounds        | 1 charge per spell level (maximum 4 for a level 4 spell) |\n| Lesser Restoration | 2                                                        |\n| Mass Cure Wounds   | 5                                                        |\n\n**_Regaining Charges._** The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff vanishes in a flash of light, lost forever.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-healing","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-power', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Power","tags":["misc","staff","very-rare","attunement"],"attune":"Requires Attunement by a Sorcerer, Warlock, or Wizard","flavor":"This staff has 20 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you gain a +2 bonus to Armor Class, saving throws, and spell attack rolls.\n\n**_Spells._** While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell                            | Charge Cost |\n|----------------------------------|-------------|\n| Cone of Cold                     | 5           |\n| Fireball (level 5 version)       | 5           |\n| Globe of Invulnerability         | 6           |\n| Hold Monster                     | 5           |\n| Levitate                         | 2           |\n| Lightning Bolt (level 5 version) | 5           |\n| Magic Missile                    | 1           |\n| Ray of Enfeeblement              | 1           |\n| Wall of Force                    | 5           |\n\n**_Regaining Charges._** The staff regains 2d8 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff retains its +2 bonus to attack rolls and damage rolls but loses all other properties. On a 20, the staff regains 1d8 + 2 charges.\n\n**_Retributive Strike._** You can take a Magic action to break the staff over your knee or against a solid surface. The staff is destroyed and releases its magic in an explosion that fills a 30-foot Emanation originating from itself. You have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take Force damage equal to 16 times the number of charges in the staff. Each other creature in the area makes a DC 17 Dexterity saving throw. On a failed save, a creature takes Force damage equal to 4 times the number of charges in the staff. On a successful save, a creature takes half as much damage.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-power","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-striking', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Striking","tags":["misc","staff","very-rare","attunement"],"attune":"Requires attunement","flavor":"This staff can be wielded as a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls made with it. The staff has 10 charges. When you hit with a melee attack using it, you can expend up to 3 charges. For each charge you expend, the target takes an extra 1d6 Force damage. Regaining Charges. The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff becomes a nonmagical Quarterstaff.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-striking","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-swarming-insects', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Swarming Insects","tags":["misc","staff","rare","attunement"],"attune":"Requires Attunement by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard","flavor":"This staff has 10 charges.\n\n**_Insect Cloud._** While holding the staff, you can take a Magic action and expend 1 charge to cause a swarm of harmless flying insects to fill a 30-foot Emanation originating from you. The insects remain for 10 minutes, making the area Heavily Obscured for creatures other than you. A strong wind (like that created by *Gust of Wind*) disperses the swarm and ends the effect.\n\n**_Spells._** While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC and spell attack modifier. The table indicates how many charges you must expend to cast the spell.\n\n| Spell         | Charge Cost |\n|---------------|-------------|\n| Giant Insect  | 4           |\n| Insect Plague | 5           |\n\n**_Regaining Charges._** The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, a swarm of insects consumes and destroys the staff, then disperses.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-swarming-insects","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-the-magi', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of the Magi","tags":["misc","staff","legendary","attunement"],"attune":"Requires Attunement by a Sorcerer, Warlock, or Wizard","flavor":"This staff has 50 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While you hold it, you gain a +2 bonus to spell attack rolls.\n\n**_Spell Absorption._** While holding the staff, you have Advantage on saving throws against spells. In addition, you can take a Reaction when another creature casts a spell that targets only you. If you do, the staff absorbs the magic of the spell, canceling its effect and gaining a number of charges equal to the absorbed spell''s level. However, if doing so brings the staff''s total number of charges above 50, the staff explodes as if you activated its Retributive Strike (see below).\n\n**_Spells._** While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell                            | Charge Cost |\n|----------------------------------|-------------|\n| Arcane Lock                      | 0           |\n| Conjure Elemental                | 7           |\n| Detect Magic                     | 0           |\n| Dispel Magic                     | 3           |\n| Enlarge/Reduce                   | 0           |\n| Fireball (level 7 version)       | 7           |\n| Flaming Sphere                   | 2           |\n| Ice Storm                        | 4           |\n| Invisibility                     | 2           |\n| Knock                            | 2           |\n| Light                            | 0           |\n| Lightning Bolt (level 7 version) | 7           |\n| Mage Hand                        | 0           |\n| Passwall                         | 5           |\n| Plane Shift                      | 7           |\n| Protection from Evil and Good    | 0           |\n| Telekinesis                      | 5           |\n| Wall of Fire                     | 4           |\n| Web                              | 2           |\n\n**_Regaining Charges._** The staff regains 4d6 + 2 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 20, the staff regains 1d12 + 1 charges.\n\n**_Retributive Strike._** You can take a Magic action to break the staff over your knee or against a solid surface. The staff is destroyed and releases its magic in an explosion that fills a 30-foot Emanation originating from itself. You have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take Force damage equal to 16 times the number of charges in the staff. Each other creature in the area makes a DC 17 Dexterity saving throw. On a failed save, a creature takes Force damage equal to 6 times the number of charges in the staff. On a successful save, a creature takes half as much damage.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-the-magi","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-the-python', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of the Python","tags":["misc","staff","uncommon","attunement"],"attune":"Requires attunement","flavor":"As a Magic action, you can throw this staff so that it lands in an unoccupied space within 10 feet of you, causing the staff to become a Giant Constrictor Snake in that space. The snake is under your control and shares your Initiative count, taking its turn immediately after yours. On your turn, you can mentally command the snake (no action required) if it is within 60 feet of you and you don''t have the Incapacitated condition. You decide what action the snake takes and where it moves during its turn, or you can issue it a general command, such as to attack your enemies or guard a location. Absent commands from you, the snake defends itself. As a Bonus Action, you can command the snake to revert to staff form in its current space, and you can''t use the staff''s property again for 1 hour. If the snake is reduced to 0 Hit Points, it dies and reverts to its staff form; the staff then shatters and is destroyed. If the snake reverts to staff form before losing all its Hit Points, it regains all of them.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-the-python","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-the-woodlands', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of the Woodlands","tags":["misc","staff","rare","attunement"],"attune":"Requires Attunement by a Druid","flavor":"This staff has 6 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you have a +2 bonus to spell attack rolls.\n\n**_Spells._** While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\n\n| Spell                    | Charge Cost |\n|--------------------------|-------------|\n| Animal Friendship        | 1           |\n| Awaken                   | 5           |\n| Barkskin                 | 2           |\n| Locate Animals or Plants | 2           |\n| Pass without Trace       | 2           |\n| Speak with Animals       | 1           |\n| Speak with Plants        | 3           |\n| Wall of Thorns           | 6           |\n\n**_Tree Form._** You can take a Magic action to plant one end of the staff in earth in an unoccupied space and expend 1 charge to transform the staff into a healthy tree. The tree is 60 feet tall and has a 5-foot-diameter trunk, and its branches at the top spread out in a 20-foot radius. The tree appears ordinary but radiates a faint aura of Transmutation magic that can be discerned with the *Detect Magic* spell. While touching the tree and using a Magic action, you return the staff to its normal form. Any creature in the tree falls when the tree reverts to a staff.\n\n**_Regaining Charges._** The staff regains 1d6 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff loses its properties and becomes a nonmagical Quarterstaff.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-the-woodlands","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-thunder-and-lightning', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Thunder and Lightning","tags":["misc","staff","very-rare","attunement"],"attune":"Requires attunement","flavor":"This staff can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. It also has the following additional properties. Once one of these properties is used, it can''t be used again until the next dawn. Lightning. When you hit with a melee attack using the staff, you can cause the target to take an extra 2d6 Lightning damage (no action required). Thunder. When you hit with a melee attack using the staff, you can cause the staff to emit a crack of thunder audible out to 300 feet (no action required). The target you hit must succeed on a DC 17 Constitution saving throw or have the Stunned condition until the end of your next turn. Thunder and Lightning. Immediately after you hit with a melee attack using the staff, you can take a Bonus Action to use the Lightning and Thunder properties (see above) at the same time. Doing so doesn''t expend the daily use of those properties, only the use of this one. Lightning Strike. You can take a Magic action to cause a bolt of lightning to leap from the staff''s tip in a Line that is 5 feet wide and 120 feet long. Each creature in that Line makes a DC 17 Dexterity saving throw, taking 9d6 Lightning damage on a failed save or half as much damage on a successful one. Thunderclap. You can take a Magic action to cause the staff to produce a thunderclap audible out to 600 feet. Every creature within a 60-foot Emanation originating from you makes a DC 17 Constitution saving throw. On a failed save, a creature takes 2d6 Thunder damage and has the Deafened condition for 1 minute. On a successful save, a creature takes half as much damage only.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-thunder-and-lightning","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_staff-of-withering', '{"h":1,"w":1,"icon":"fa-staff-snake","name":"Staff of Withering","tags":["misc","staff","rare","attunement"],"attune":"Requires attunement","flavor":"This staff has 3 charges and regains 1d3 expended charges daily at dawn. The staff can be wielded as a magic Quarterstaff. On a hit, it deals damage as a normal Quarterstaff, and you can expend 1 charge to deal an extra 2d10 Necrotic damage to the target and force it to make a DC 15 Constitution saving throw. On a failed save, the target has Disadvantage for 1 hour on any ability check or saving throw that uses Strength or Constitution.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_staff-of-withering","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_stone-of-controlling-earth-elementals', '{"h":1,"w":1,"icon":"fa-gem","name":"Stone of Controlling Earth Elementals","tags":["misc","wondrous-item","rare"],"flavor":"While touching this 5-pound stone to the ground, you can take a Magic action to summon an Earth Elemental. The elemental appears in an unoccupied space you choose within 30 feet of yourself, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The stone can''t be used this way again until the next dawn.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_stone-of-controlling-earth-elementals","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_stone-of-good-luck-luckstone', '{"h":1,"w":1,"icon":"fa-gem","name":"Stone of Good Luck (Luckstone)","tags":["misc","wondrous-item","uncommon","attunement"],"attune":"Requires attunement","flavor":"While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_stone-of-good-luck-luckstone","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_string', '{"h":1,"w":1,"icon":"fa-cube","name":"String","tags":["misc","adventuring-gear","common"],"value":0.1,"flavor":"String is 10 feet long. You can tie a knot in it as a Utilize action.","rarity":"common","source":"srd","weight":0,"srd_key":"srd-2024_string","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_studded-leather-armor', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Studded Leather Armor","slot":"armor","tags":["armor","common","armor:light"],"value":45,"baseAc":12,"flavor":"A studded leather armor.","rarity":"common","source":"srd","weight":13,"srd_key":"srd-2024_studded-leather-armor","acAddDex":true,"category":"armor","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_studded-leather-armor-plus-1', '{"h":1,"w":2,"icon":"fa-shield-halved","name":"Studded Leather Armor (+1)","slot":"armor","tags":["armor","uncommon","magic+1","armor:light"],"baseAc":12,"flavor":"You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity.","rarity":"uncommon","source":"srd","weight":13,"effects":{"ac":1},"srd_key":"srd-2024_studded-leather-armor-plus-1","acAddDex":true,"category":"armor"}'::jsonb)
