insert into item_catalog (id, data) values ('srd-2024_tinderbox', '{"h":1,"w":1,"icon":"fa-cube","name":"Tinderbox","tags":["misc","adventuring-gear","common"],"value":0.5,"flavor":"A Tinderbox is a small container holding flint, fire steel, and tinder (usually dry cloth soaked in light oil) used to kindle a fire. Using it to light a Candle, Lamp, Lantern, or Torch—or anything else with exposed fuel—takes a Bonus Action. Lighting any other fire takes 1 minute.","rarity":"common","source":"srd","weight":1,"srd_key":"srd-2024_tinderbox","category":"misc","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_tinkers-tools', '{"h":1,"w":1,"icon":"fa-screwdriver-wrench","name":"Tinker''s Tools (50 GP)","tags":["tool","tools","common"],"value":50,"flavor":"Ability: Dexterity. Utilize: Assemble a Tiny item composed of scrap, which falls apart in 1 minute (DC 20). Craft: Musket, Pistol, Bell, Bullseye Lantern, Flask, Hooded Lantern, Hunting Trap, Lock, Manacles, Mirror, Shovel, Signal Whistle, Tinderbox","rarity":"common","source":"srd","weight":10,"srd_key":"srd-2024_tinkers-tools","category":"tool","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_tome-of-clear-thought', '{"h":1,"w":1,"icon":"fa-book","name":"Tome of Clear Thought","tags":["misc","wondrous-item","very-rare"],"flavor":"This book contains memory and logic exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Intelligence increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_tome-of-clear-thought","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_tome-of-leadership-and-influence', '{"h":1,"w":1,"icon":"fa-book","name":"Tome of Leadership and Influence","tags":["misc","wondrous-item","very-rare"],"flavor":"This book contains guidelines for influencing and charming others, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Charisma increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_tome-of-leadership-and-influence","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
