  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_torch', '{"h":1,"w":1,"icon":"fa-fire","name":"Torch","tags":["weapon","common"],"value":0.01,"flavor":"A Torch burns for 1 hour, casting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. When you take the Attack action, you can attack with the Torch, using it as a Simple Melee weapon. On a hit, the target takes 1 Fire damage.","rarity":"common","source":"srd","weight":1,"srd_key":"srd-2024_torch","category":"weapon","valueUnit":"gp"}'::jsonb)
