insert into item_catalog (id, data) values ('srd-2024_vorpal-glaive', '{"h":3,"w":1,"icon":"fa-location-arrow","name":"Vorpal Glaive","tags":["weapon","legendary","slashing","graze","heavy","reach","two-handed","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage.\n\nWhen you use this weapon to attack a creature that has at least one head and roll a 20 on the d20 for the attack roll, you cut off one of the creature''s heads. The creature dies if it can''t survive without the lost head. A creature is immune to this effect if it has Immunity to Slashing damage, if it doesn''t have or need a head, or if the GM decides that the creature is too big for its head to be cut off with this weapon. Such a creature instead takes an extra 30 Slashing damage from the hit. If the creature has Legendary Resistance, it can expend one daily use of that trait to avoid losing its head, taking the extra damage instead.","rarity":"legendary","source":"srd","weight":6,"srd_key":"srd-2024_vorpal-glaive","category":"weapon","damageDice":"1d10","properties":["Graze","Heavy","Reach","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_vorpal-greatsword', '{"h":3,"w":1,"icon":"fa-khanda","name":"Vorpal Greatsword","tags":["weapon","legendary","slashing","graze","heavy","two-handed","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage.\n\nWhen you use this weapon to attack a creature that has at least one head and roll a 20 on the d20 for the attack roll, you cut off one of the creature''s heads. The creature dies if it can''t survive without the lost head. A creature is immune to this effect if it has Immunity to Slashing damage, if it doesn''t have or need a head, or if the GM decides that the creature is too big for its head to be cut off with this weapon. Such a creature instead takes an extra 30 Slashing damage from the hit. If the creature has Legendary Resistance, it can expend one daily use of that trait to avoid losing its head, taking the extra damage instead.","rarity":"legendary","source":"srd","weight":6,"srd_key":"srd-2024_vorpal-greatsword","category":"weapon","damageDice":"2d6","properties":["Graze","Heavy","Two-Handed"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_vorpal-longsword', '{"h":2,"w":1,"icon":"fa-khanda","name":"Vorpal Longsword","tags":["weapon","legendary","slashing","sap","versatile","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage.\n\nWhen you use this weapon to attack a creature that has at least one head and roll a 20 on the d20 for the attack roll, you cut off one of the creature''s heads. The creature dies if it can''t survive without the lost head. A creature is immune to this effect if it has Immunity to Slashing damage, if it doesn''t have or need a head, or if the GM decides that the creature is too big for its head to be cut off with this weapon. Such a creature instead takes an extra 30 Slashing damage from the hit. If the creature has Legendary Resistance, it can expend one daily use of that trait to avoid losing its head, taking the extra damage instead.","rarity":"legendary","source":"srd","weight":3,"srd_key":"srd-2024_vorpal-longsword","category":"weapon","damageDice":"1d8","properties":["Sap","Versatile"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_vorpal-scimitar', '{"h":1,"w":1,"icon":"fa-khanda","name":"Vorpal Scimitar","tags":["weapon","legendary","slashing","finesse","light","nick","attunement"],"type":"Slashing","attune":"Requires attunement","flavor":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage.\n\nWhen you use this weapon to attack a creature that has at least one head and roll a 20 on the d20 for the attack roll, you cut off one of the creature''s heads. The creature dies if it can''t survive without the lost head. A creature is immune to this effect if it has Immunity to Slashing damage, if it doesn''t have or need a head, or if the GM decides that the creature is too big for its head to be cut off with this weapon. Such a creature instead takes an extra 30 Slashing damage from the hit. If the creature has Legendary Resistance, it can expend one daily use of that trait to avoid losing its head, taking the extra damage instead.","rarity":"legendary","source":"srd","weight":3,"ability":"finesse","srd_key":"srd-2024_vorpal-scimitar","category":"weapon","damageDice":"1d6","properties":["Finesse","Light","Nick"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-binding', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Binding","tags":["misc","wand","rare","attunement"],"attune":"Requires attunement","flavor":"This wand has 7 charges.\n\n**_Spells._** While holding the wand, you can cast one of the spells (save DC 17) on the following table from it. The table indicates how many charges you must expend to cast the spell.\n\n| Spell        | Charge Cost |\n|--------------|-------------|\n| Hold Monster | 5           |\n| Hold Person  | 2           |\n\n**_Regaining Charges._** The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-binding","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-enemy-detection', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Enemy Detection","tags":["misc","wand","rare","attunement"],"attune":"Requires attunement","flavor":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge. For 1 minute, you know the direction of the nearest creature Hostile to you within 60 feet, but not its distance from you. The wand can sense the presence of Hostile creatures that are Invisible, ethereal, disguised, or hidden, as well as those in plain sight. The effect ends if you stop holding the wand. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-enemy-detection","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-fireballs', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Fireballs","tags":["misc","wand","rare","attunement"],"attune":"Requires Attunement by a Spellcaster","flavor":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Fireball (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell''s level by 1 for each additional charge you expend. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-fireballs","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-lightning-bolts', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Lightning Bolts","tags":["misc","wand","rare","attunement"],"attune":"Requires Attunement by a Spellcaster","flavor":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Lightning Bolt (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell''s level by 1 for each additional charge you expend. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-lightning-bolts","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-magic-detection', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Magic Detection","tags":["misc","wand","uncommon"],"flavor":"This wand has 3 charges. While holding it, you can expend 1 charge to cast Detect Magic from it. The wand regains 1d3 expended charges daily at dawn.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-magic-detection","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-magic-missiles', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Magic Missiles","tags":["misc","wand","uncommon"],"flavor":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Magic Missile from it. For 1 charge, you cast the level 1 version of the spell. You can increase the spell''s level by 1 for each additional charge you expend. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-magic-missiles","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-paralysis', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Paralysis","tags":["misc","wand","rare","attunement"],"attune":"Requires Attunement by a Spellcaster","flavor":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge to cause a thin blue ray to streak from the tip toward a creature you can see within 60 feet of yourself. The target must succeed on a DC 15 Constitution saving throw or have the Paralyzed condition for 1 minute. At the end of each of the target''s turns, it repeats the save, ending the effect on itself on a success. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","rarity":"rare","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-paralysis","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-polymorph', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Polymorph","tags":["misc","wand","very-rare","attunement"],"attune":"Requires Attunement by a Spellcaster","flavor":"This wand has 7 charges. While holding it, you can expend 1 charge to cast Polymorph (save DC 15) from it. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand''s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed.","rarity":"very-rare","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-polymorph","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-secrets', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of Secrets","tags":["misc","wand","uncommon"],"flavor":"This wand has 3 charges and regains 1d3 expended charges daily at dawn. While holding it, you can take a Magic action to expend 1 charge, and if a secret door or trap is within 60 feet of you, the wand pulses and points at the one nearest to you.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-secrets","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_wand-of-the-war-mage-plus-1', '{"h":1,"w":1,"icon":"fa-wand-sparkles","name":"Wand of the War Mage +1","tags":["misc","wand","uncommon","attunement"],"attune":"Requires attunement","flavor":"While holding this wand, you gain a bonus to spell attack rolls determined by the wand''s rarity (Uncommon +1, Rare +2, Very Rare +3). In addition, you ignore Half Cover when making a spell attack roll.","rarity":"uncommon","source":"srd","weight":0,"srd_key":"srd-2024_wand-of-the-war-mage-plus-1","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
