insert into item_catalog (id, data) values ('srd-2024_weapon-of-warning-battleaxe', '{"h":2,"w":1,"icon":"fa-khanda","name":"Weapon of Warning (Battleaxe)","tags":["weapon","uncommon","slashing","topple","versatile"],"type":"Slashing","flavor":"As long as this weapon is within your reach and you are attuned to it, you and allies within 30 feet of you gain the following benefits.\n\n**Alarm.** The weapon magically awakens each subject who is sleeping naturally when combat begins. This benefit doesn''t wake a subject from magically induced sleep.\n\n**Supernatural Readiness.** Each subject has Advantage on its Initiative rolls.","rarity":"uncommon","source":"srd","weight":4,"srd_key":"srd-2024_weapon-of-warning-battleaxe","category":"weapon","damageDice":"1d8","properties":["Topple","Versatile"]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
