insert into item_catalog (id, data) values ('srd-2024_weavers-tools', '{"h":1,"w":1,"icon":"fa-screwdriver-wrench","name":"Weaver''s Tools (1 GP)","tags":["tool","tools","common"],"value":1,"flavor":"Ability: Dexterity. Utilize: Mend a tear in clothing (DC 10), or sew a Tiny design (DC 10). Craft: Padded Armor, Basket, Bedroll, Blanket, Fine Clothes, Net, Robe, Rope, Sack, String, Tent, Traveler''s Clothes","rarity":"common","source":"srd","weight":5,"srd_key":"srd-2024_weavers-tools","category":"tool","valueUnit":"gp"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into item_catalog (id, data) values ('srd-2024_well-of-many-worlds', '{"h":1,"w":1,"icon":"fa-cube","name":"Well of Many Worlds","tags":["misc","wondrous-item","legendary"],"flavor":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter. You can take a Magic action to unfold the Well of Many Worlds and place it on a solid surface, whereupon it forms a two-way, 6-foot-diameter, circular portal to another world or plane of existence. Each time the item opens a portal, the GM decides where it leads. The portal remains open until a creature within 5 feet of it takes a Magic action to close it by taking hold of the edges of the cloth and folding it up. Once the Well of Many Worlds has opened a portal, it can''t do so again for 1d8 hours.","rarity":"legendary","source":"srd","weight":0,"srd_key":"srd-2024_well-of-many-worlds","category":"misc"}'::jsonb)
  on conflict (id) do update set data = excluded.data;
