insert into item_catalog (id, data) values ('srd-2024_whip-plus-1', '{"h":2,"w":1,"icon":"fa-khanda","name":"Whip (+1)","tags":["weapon","uncommon","slashing","finesse","reach","slow","magic+1"],"type":"Slashing","graph":[{"id":"srd-2024_whip-plus-1_bonus","op":"add","label":"+1 magic weapon","value":"1"}],"flavor":"You have a bonus to attack rolls and damage rolls made with this magic weapon. The bonus is determined by the weapon''s rarity.","rarity":"uncommon","source":"srd","weight":3,"ability":"finesse","srd_key":"srd-2024_whip-plus-1","category":"weapon","damageDice":"1d4","properties":["Finesse","Reach","Slow"]}'::jsonb)
