insert into effect_catalog (id, data) values ('fx-bless', '{"desc":"A quiet favour settles over the blessed. Add 1d4 to every attack roll and every saving throw made while it holds — rolled by the player, at the moment of the roll.","icon":"fa-hands-praying","kind":"buff","mods":[],"name":"Bless","tags":["spell","divine"],"flags":[]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into effect_catalog (id, data) values ('fx-charmed', '{"desc":"You cannot attack the charmer or target them with harmful abilities, and the charmer has Advantage on ability checks to interact with you socially.","icon":"gi:lorc/charm","kind":"condition","mods":[],"name":"Charmed","tags":["charmed","standard"],"flags":[{"mode":"disadvantage","target":"ability checks"}]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into effect_catalog (id, data) values ('fx-frightened', '{"desc":"While the source of your fear is within line of sight you have Disadvantage on ability checks and attack rolls, and you cannot willingly move closer to it.","icon":"gi:lorc/terror","kind":"condition","mods":[],"name":"Frightened","tags":["frightened","standard"],"flags":[{"mode":"disadvantage","target":"ability checks"},{"mode":"disadvantage","target":"attack rolls"}]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into effect_catalog (id, data) values ('fx-giant-strength', '{"desc":"Thews swell with borrowed weight. Strength is SET to the draught''s fixed value rather than raised — a weak arm and a strong one end at the same number.","icon":"fa-hand-fist","kind":"buff","mods":[{"amt":21,"set":true,"stat":"STR"}],"name":"Giant''s Strength","tags":["potion","item"],"flags":[]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into effect_catalog (id, data) values ('fx-haste', '{"desc":"The world thickens and slows around the hastened. Each turn they may take one additional limited action — attack once, dash, disengage, hide, or use an object — and nothing more than that. When it ends the body collects on the borrowed speed: the target can neither move nor act until after their next turn.","icon":"fa-bolt","kind":"buff","mods":[{"amt":2,"stat":"AC"}],"name":"Haste","tags":["spell","transmutation","movement"],"flags":[{"mode":"advantage","target":"DEX saves"}]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
