  on conflict (id) do update set data = excluded.data;
insert into effect_catalog (id, data) values ('fx-silvered', '{"desc":"Silver-washed heads for the things that shrug off plain steel.","icon":"fa-location-arrow","kind":"buff","mods":[{"amt":1,"stat":"Damage"}],"name":"Silvered Edge","tags":["weapon","ammo"],"flags":[]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
