  on conflict (id) do update set data = excluded.data;
insert into effect_catalog (id, data) values ('fx-warding-band', '{"desc":"A plain band, cool against the skin, that turns aside the worst of a blow and steadies the nerve against everything else.","icon":"fa-ring","kind":"buff","mods":[{"amt":1,"stat":"AC"},{"amt":1,"stat":"Saves"}],"name":"Warding Band","tags":["magic_item","ward"],"flags":[]}'::jsonb)
