insert into feature_catalog (id, data, draft) values ('catf-elven-stealth', '{"icon":"fa-user-ninja","kind":"equipment","name":"Elven Concealment","vars":[{"kind":"stored","name":"whileHoodIsUp","type":"bool","label":"While hood is up","scope":"player","initial":false}],"graph":[{"id":"edbj2i7","op":"adv","once":false,"when":"whileHoodIsUp","label":"While hood is up","target":["roll:check.stealth"]}],"usage":"While hood is up","folder":"Test","source":"Cloak of Elvenkind","category":"other","published":true,"deep_description":"While you wear this cloak with its hood up, Wisdom (Perception) checks made to see you have disadvantage, and you have advantage on Dexterity (Stealth) checks made to hide, as the cloak''s color shifts to camouflage you.","light_description":"**Advantage** on Stealth checks; perception checks to see you have **disadvantage**."}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into feature_catalog (id, data, draft) values ('catf-inspiring-presence', '{"icon":"fa-comments","kind":"levelup","name":"Inspiring Presence","uses":{"max":1,"current":1},"order":1.0615234375,"usage":"1/long rest","folder":"Test","source":"Roleplay boon","category":"background","recharge":"long","published":true,"deep_description":"Earned in play — a word from you steadies a companion''s hand. The DM adjudicates the moment; this card is the reminder that you can spend it.","light_description":"Once per long rest, grant an ally within earshot **advantage** on their next ability check."}'::jsonb, null)
