insert into race_catalog (id, data, draft) values ('srd-2024_dwarf', '{"desc":"Dwarves are compact and dense, and they endure. Their kind measure time in the way stone does — a grudge or a debt outlives the one who made it — and they read the rock around them the way others read a room. Poison finds little purchase in dwarven blood, and a dwarf standing on stone knows what moves beneath it.","icon":"fa-user","name":"Dwarf","tags":["species","dwarf","size:medium"],"vars":[],"graph":[{"id":"dwarf_speed","op":"boost","stat":"Speed","label":"Dwarf speed","value":30},{"id":"dwarf_dark","op":"boost","stat":"Darkvision","label":"Dwarf darkvision","value":120}],"source":"srd","srd_key":"srd-2024_dwarf","features":[{"feature_id":"srd-2024_dwarf_dwarven_resilience"},{"feature_id":"srd-2024_dwarf_dwarven_toughness"},{"feature_id":"srd-2024_dwarf_stonecunning"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_elf', '{"desc":"Elves are of the Feywild as much as of the world, and it shows: they do not sleep so much as remember, magic slides off them where it catches on others, and the dark holds nothing they cannot see. Which court an elf descends from — [Drow]{violet}, [High]{cyan}, or [Wood]{good} — decides the magic that comes to them without being learned.","icon":"fa-user","name":"Elf","tags":["species","elf","size:medium"],"vars":[],"graph":[{"id":"elf_speed","op":"boost","stat":"Speed","label":"Elf speed","value":30},{"id":"elf_dark","op":"boost","stat":"Darkvision","label":"Elf darkvision","value":60}],"source":"srd","srd_key":"srd-2024_elf","features":[{"feature_id":"srd-2024_elf_elven_lineage"},{"feature_id":"srd-2024_elf_fey_ancestry"},{"feature_id":"srd-2024_elf_keen_senses"},{"feature_id":"srd-2024_elf_trance"}],"languages":[],"published":true,"skillChoices":["insight","perception","survival"],"skillChooseN":1,"subraceLabel":"Elven Lineage","proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_elf-drow', '{"desc":"You descend from the [Drow]{violet}. Your Darkvision reaches **120 feet**, and you know the *Dancing Lights* cantrip.","icon":"fa-moon","name":"Drow","tags":["species","elf","elven_lineage","drow"],"vars":[],"color":"#8b6fd4","graph":[{"id":"drow_dark","op":"boost","stat":"Darkvision","label":"Drow Darkvision","value":120}],"parent":"srd-2024_elf","source":"srd","srd_key":"srd-2024_elf-drow","features":[{"when":"level >= 3","feature_id":"srd-2024_elf_lineage_drow_faerie_fire"},{"when":"level >= 5","feature_id":"srd-2024_elf_lineage_drow_darkness"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_elf-high', '{"desc":"You descend from the [High Elves]{cyan}. You know the *Prestidigitation* cantrip, and on every Long Rest you may swap it for a different cantrip from the Wizard spell list.","icon":"fa-hat-wizard","name":"High Elf","tags":["species","elf","elven_lineage","high_elf"],"vars":[],"color":"#5fb6d6","graph":[],"parent":"srd-2024_elf","source":"srd","srd_key":"srd-2024_elf-high","features":[{"when":"level >= 3","feature_id":"srd-2024_elf_lineage_high_detect_magic"},{"when":"level >= 5","feature_id":"srd-2024_elf_lineage_high_misty_step"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_elf-wood', '{"desc":"You descend from the [Wood Elves]{good}. Your Speed is **35 feet**, and you know the *Druidcraft* cantrip.","icon":"fa-tree","name":"Wood Elf","tags":["species","elf","elven_lineage","wood_elf"],"vars":[],"color":"#6fae6f","graph":[{"id":"wood_speed","op":"boost","stat":"Speed","label":"Wood Elf Speed","value":5}],"parent":"srd-2024_elf","source":"srd","srd_key":"srd-2024_elf-wood","features":[{"when":"level >= 3","feature_id":"srd-2024_elf_lineage_wood_longstrider"},{"when":"level >= 5","feature_id":"srd-2024_elf_lineage_wood_pass_without_trace"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_gnome', '{"desc":"Gnomes are small, quick, and almost impossible to get a grip on mentally — charms slide off them, illusions do not take, and a gnome told what to think will cheerfully agree and do otherwise. Their kind run to two lines: those raised among trees, and those raised among tools.","icon":"fa-user","name":"Gnome","tags":["species","gnome","size:small"],"vars":[],"graph":[{"id":"gnome_speed","op":"boost","stat":"Speed","label":"Gnome speed","value":30},{"id":"gnome_dark","op":"boost","stat":"Darkvision","label":"Gnome darkvision","value":60}],"source":"srd","srd_key":"srd-2024_gnome","features":[{"feature_id":"srd-2024_gnome_gnomish_cunning"},{"feature_id":"srd-2024_gnome_gnomish_lineage"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"subraceLabel":"Gnomish Lineage","proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_gnome-forest', '{"desc":"You were raised among trees. You know the *Minor Illusion* cantrip, and *Speak with Animals* is always prepared for you.","icon":"fa-tree","name":"Forest Gnome","tags":["species","gnome","gnomish_lineage","forest_gnome"],"vars":[],"color":"#6fae6f","graph":[],"parent":"srd-2024_gnome","source":"srd","srd_key":"srd-2024_gnome-forest","features":[{"feature_id":"srd-2024_gnome_lineage_speak-with-animals"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_gnome-rock', '{"desc":"You were raised among tools. You know the *Mending* and *Prestidigitation* cantrips, and you can build things that shouldn''t work and do.","icon":"fa-gear","name":"Rock Gnome","tags":["species","gnome","gnomish_lineage","rock_gnome"],"vars":[],"color":"#b08a5a","graph":[],"parent":"srd-2024_gnome","source":"srd","srd_key":"srd-2024_gnome-rock","features":[{"feature_id":"srd-2024_gnome_lineage_tinker"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_goliath', '{"desc":"Goliaths stand a head above most and are built to match — they carry what others drag, and shrug off a grapple that would pin anyone else. Somewhere back along the line there was a giant, and which kind decides what a goliath can do that no amount of muscle explains.","icon":"fa-user","name":"Goliath","tags":["species","goliath","size:medium"],"vars":[],"graph":[{"id":"goliath_speed","op":"boost","stat":"Speed","label":"Goliath speed","value":35}],"source":"srd","srd_key":"srd-2024_goliath","features":[{"feature_id":"srd-2024_goliath_giant_ancestry"},{"when":"level >= 5","feature_id":"srd-2024_goliath_large_form"},{"feature_id":"srd-2024_goliath_powerful_build"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"subraceLabel":"Giant Ancestry","proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
