insert into race_catalog (id, data, draft) values ('srd-2024_goliath-fire', '{"desc":"Your line runs back to a **fire giant**. Your boon is *Fire''s Burn* — an extra 1d10 Fire damage on a hit.","icon":"fa-fire","name":"Fire Giant","tags":["species","goliath","giant_ancestry","fire_giant"],"vars":[],"color":"#d1564e","graph":[],"parent":"srd-2024_goliath","source":"srd","srd_key":"srd-2024_goliath-fire","features":[{"feature_id":"srd-2024_goliath_boon_fires-burn"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
