insert into race_catalog (id, data, draft) values ('srd-2024_halfling', '{"desc":"Halflings are small, and have made a study of what small is good for: going unnoticed, slipping between things, and being underestimated by whatever is about to regret it. They are famously hard to frighten and famously lucky, and the two are probably related.","icon":"fa-user","name":"Halfling","tags":["species","halfling","size:small"],"vars":[],"graph":[{"id":"halfling_speed","op":"boost","stat":"Speed","label":"Halfling speed","value":30}],"source":"srd","srd_key":"srd-2024_halfling","features":[{"feature_id":"srd-2024_halfling_brave"},{"feature_id":"srd-2024_halfling_halfling_nimbleness"},{"feature_id":"srd-2024_halfling_luck"},{"feature_id":"srd-2024_halfling_naturally_stealthy"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_human', '{"desc":"Humans arrive without a specialism and make one anyway. What they have instead of long sight or dark vision is range — they take up trades their parents never heard of, learn a knack from whoever is nearest, and turn up in every corner of the world already halfway competent at whatever it demands.","icon":"fa-user","name":"Human","tags":["species","human","size:medium"],"vars":[],"graph":[{"id":"human_speed","op":"boost","stat":"Speed","label":"Human speed","value":30}],"source":"srd","srd_key":"srd-2024_human","features":[{"feature_id":"srd-2024_human_resourceful"},{"feature_id":"srd-2024_human_skillful"},{"feature_id":"srd-2024_human_versatile"}],"languages":[],"published":true,"skillChoices":["acrobatics","animalHandling","arcana","athletics","deception","history","insight","intimidation","investigation","medicine","nature","perception","performance","persuasion","religion","sleightOfHand","stealth","survival"],"skillChooseN":1,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_orc', '{"desc":"Orcs carry the endurance of Gruumsh: they run further than they should be able to, and they get back up from things that should have finished them. Their eyes take in more of the dark than most species manage, and what looks like fury from outside is usually just refusal to stop.","icon":"fa-user","name":"Orc","tags":["species","orc","size:medium"],"vars":[],"graph":[{"id":"orc_speed","op":"boost","stat":"Speed","label":"Orc speed","value":30},{"id":"orc_dark","op":"boost","stat":"Darkvision","label":"Orc darkvision","value":120}],"source":"srd","srd_key":"srd-2024_orc","features":[{"feature_id":"srd-2024_orc_adrenaline_rush"},{"feature_id":"srd-2024_orc_relentless_endurance"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_tiefling', '{"desc":"A tiefling carries something inherited from the Lower Planes — not a choice made, and rarely one made by them. It shows in the horns, in the eyes that work in the dark, and in a resistance to whichever harm their line came by honestly.","icon":"fa-user","name":"Tiefling","tags":["species","tiefling","size:medium"],"vars":[],"graph":[{"id":"tiefling_speed","op":"boost","stat":"Speed","label":"Tiefling speed","value":30},{"id":"tiefling_dark","op":"boost","stat":"Darkvision","label":"Tiefling darkvision","value":60}],"source":"srd","srd_key":"srd-2024_tiefling","features":[{"feature_id":"srd-2024_tiefling_fiendish_legacy"},{"feature_id":"srd-2024_tiefling_otherworldly_presence"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"subraceLabel":"Fiendish Legacy","proficiencies":{},"languageChooseN":0}'::jsonb, null)
  on conflict (id) do update set data = excluded.data, draft = excluded.draft;
insert into race_catalog (id, data, draft) values ('srd-2024_tiefling-abyssal', '{"desc":"Your line runs back to the Abyss. You have Resistance to [Poison]{poison} damage, and you know the *Poison Spray* cantrip.","icon":"fa-skull-crossbones","name":"Abyssal","tags":["species","tiefling","fiendish_legacy","abyssal"],"vars":[],"color":"#7fae5f","graph":[{"id":"legacy_resist","op":"resist","label":"Abyssal Legacy","target":["tag:poison"]}],"parent":"srd-2024_tiefling","source":"srd","srd_key":"srd-2024_tiefling-abyssal","features":[{"when":"level >= 3","feature_id":"srd-2024_tiefling_legacy_abyssal_ray_of_sickness"},{"when":"level >= 5","feature_id":"srd-2024_tiefling_legacy_abyssal_hold_person"}],"languages":[],"published":true,"skillChoices":[],"skillChooseN":0,"proficiencies":{},"languageChooseN":0}'::jsonb, null)
