insert into shard_tree_catalog (id, data) values ('cinder', '{"id":"cinder","icon":"fa-fire","name":"Shard of Cinder","nodes":[{"id":"core","cost":0,"icon":"fa-fire","name":"Ember Core","tier":0,"angle":0,"branch":"core","effect":"Base attunement. Your unarmed strikes deal +1 fire damage.","prereqs":[]},{"id":"em_1","cost":1,"icon":"fa-fire-flame-simple","name":"Kindle","tier":1,"angle":-60,"branch":"ember","effect":"Ignite a flammable object you touch as a bonus action.","prereqs":["core"]},{"id":"ash_1","cost":1,"icon":"fa-shoe-prints","name":"Ashen Step","tier":1,"angle":120,"branch":"ash","effect":"Leave no tracks; advantage on Stealth in smoke or dust.","prereqs":[]}],"flavor":"Draft. Runs hot in the pocket.","module":"Thermal Output","rarity":"Very Rare","baseMods":{},"branches":{"ash":"Ash","apex":"Apex","core":"Core","ember":"Ember"},"capacity":7,"published":false,"attuneRule":"Requires attunement · occupies 1 of 2 shard slots","baseDetails":[{"l":"Fire Resistance","v":"Yes"}],"baseFeatures":[]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into shard_tree_catalog (id, data) values ('echo', '{"id":"echo","icon":"fa-tower-broadcast","name":"Shard of Echo","nodes":[{"id":"core","cost":0,"icon":"fa-tower-broadcast","name":"Relay Core","tier":0,"angle":0,"branch":"core","effect":"Base attunement. You may reroll one Intelligence check per rest.","prereqs":[]},{"id":"sig_1","cost":1,"icon":"fa-signal","name":"Carrier Wave","tier":1,"angle":-70,"branch":"signal","effect":"You can speak telepathically to one creature you can see within 30 ft.","prereqs":["core"]},{"id":"rec_1","cost":1,"icon":"fa-brain","name":"Perfect Recall","tier":1,"angle":70,"branch":"recall","effect":"You remember anything you have seen or heard in the past month.","prereqs":["core"]},{"id":"sig_2","cost":2,"icon":"fa-wave-square","name":"Interference","tier":2,"angle":-100,"branch":"signal","effect":"As a reaction, impose disadvantage on one enemy spell attack within 60 ft.","prereqs":["sig_1"]},{"id":"rec_2","cost":2,"icon":"fa-book-open","name":"Borrowed Skill","tier":2,"angle":100,"branch":"recall","effect":"Gain proficiency in one skill an ally within 30 ft has, for one hour.","prereqs":["rec_1"]},{"id":"apex","cost":3,"icon":"fa-star","name":"Full Duplex","tier":3,"angle":0,"branch":"apex","effect":"The party shares one pooled reaction per round while within 60 ft of you.","prereqs":["sig_2","rec_2"]}],"flavor":"It hums at a frequency just under hearing. Everyone in the room finishes their sentences a half-beat faster.","module":"Cognitive Relay","rarity":"Rare","baseMods":{"skills":{"perception":1},"abilities":{"int":2}},"branches":{"apex":"Apex","core":"Core","recall":"Recall","signal":"Signal"},"capacity":6,"published":true,"attuneRule":"Requires attunement · occupies 1 of 2 shard slots","baseDetails":[{"l":"Range","v":"30 ft"}],"baseFeatures":[]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into shard_tree_catalog (id, data) values ('guide', '{"id":"guide","icon":"fa-eye","name":"G.U.I.D.E. Shard","nodes":[{"id":"core","cost":0,"icon":"fa-eye","name":"G.U.I.D.E. Core","tier":0,"angle":0,"branch":"core","effect":"The base link. There is no lattice to spend on — this shard does not calibrate.","prereqs":[]}],"flavor":"Global Unification Initiative for Directed Entities. Issued, not found — it was never yours to attune.","module":"Global Unification Initiative for Directed Entities","rarity":"Legendary","baseMods":{},"branches":{"core":"Core"},"capacity":0,"basePerks":[{"icon":"fa-skull","name":"Combat Assitance","description":""},{"icon":"fa-wave-square","name":"Real-Time Map Sync","description":""},{"icon":"fa-gem","name":"Quest Tracking","description":""}],"published":true,"attuneRule":"Permanent · slot 1 · cannot be ejected","baseDetails":[{"l":"Status","v":"Permanent"},{"l":"Origin","v":"Issued"}],"baseFeatures":[]}'::jsonb)
  on conflict (id) do update set data = excluded.data;
insert into shard_tree_catalog (id, data) values ('null_', '{"id":"null_","icon":"fa-question","name":"Shard of the Lady","nodes":[{"id":"core","cost":0,"icon":"fa-question","mods":{"abilities":{"str":1}},"name":"???","tier":0,"angle":0,"branch":"core","effect":"Node data returns empty. The tree exists. It has not been written by anyone at this table.","prereqs":[],"features":[{"id":"sf-catf-elven-stealth-1786795363521","icon":"fa-user-ninja","kind":"equipment","name":"Elven Concealment","usage":"While hood is up","source":"Cloak of Elvenkind","category":"other","feature_id":"catf-elven-stealth","deep_description":"While you wear this cloak with its hood up, Wisdom (Perception) checks made to see you have disadvantage, and you have advantage on Dexterity (Stealth) checks made to hide, as the cloak''s color shifts to camouflage you.","light_description":"**Advantage** on Stealth checks; perception checks to see you have **disadvantage**."}]}],"flavor":"","module":"—— UNRESOLVED ——","rarity":"Legendary","baseMods":{},"branches":{"core":"Core"},"capacity":0,"published":true,"attuneRule":"—","baseDetails":[],"baseFeatures":[]}'::jsonb)
