insert into shard_tree_catalog (id, data) values ('vigor', '{"id":"vigor","icon":"fa-gem","name":"Shard of Vigor","nodes":[{"id":"core","cost":0,"icon":"fa-gem","name":"Shard Core","tier":0,"angle":0,"branch":"core","effect":"Base attunement. +2 STR, +5 max HP.","prereqs":[]},{"id":"might_1","cost":1,"icon":"fa-hand-fist","mods":{"abilities":{"str":1}},"name":"Hardened Sinew","tier":1,"angle":-90,"branch":"might","effect":"+1 STR.","prereqs":["core"]},{"id":"vit_1","cost":1,"icon":"fa-droplet","mods":{"maxHp":5},"name":"Deep Reserves","tier":1,"angle":90,"branch":"vitality","effect":"+5 max HP.","prereqs":["core"]},{"id":"grit_1","cost":1,"icon":"fa-anchor","mods":{"maxHp":2},"name":"True Grit","tier":1,"angle":180,"branch":"grit","effect":"+2 max HP and advantage on death saving throws.","prereqs":["core"]},{"id":"might_2","cost":1,"icon":"fa-dumbbell","mods":{"carryMult":2},"name":"Powerful Build","tier":2,"angle":-120,"branch":"might","effect":"Lifting and carrying capacity doubled; advantage on STR (Athletics) checks.","prereqs":["might_1"]},{"id":"might_2b","cost":1,"icon":"fa-explosion","name":"Reckless Power","tier":2,"angle":-60,"branch":"might","effect":"Once per turn you may take a -2 penalty to AC until your next turn to deal +1d6 damage on a melee hit.","prereqs":["might_1"]},{"id":"vit_2","cost":1,"icon":"fa-shield-heart","mods":{"maxHp":5},"name":"Iron Constitution","tier":2,"angle":120,"branch":"vitality","effect":"+5 max HP; advantage on saving throws against being poisoned.","prereqs":["vit_1"]},{"id":"vit_2b","cost":1,"icon":"fa-shield","name":"Toughened Hide","tier":2,"angle":60,"branch":"vitality","effect":"While you wear no heavy armor, your AC increases by 1.","prereqs":["vit_1"]},{"id":"grit_2","cost":1,"icon":"fa-bolt","name":"Adrenal Surge","tier":2,"angle":180,"branch":"grit","effect":"When you drop below half your max HP, gain temporary HP equal to your level (once per rest).","prereqs":["grit_1"]},{"id":"might_3","cost":2,"icon":"fa-hammer","name":"Crushing Strikes","tier":3,"angle":-45,"branch":"might","effect":"+1 melee weapon damage.","prereqs":["might_2b"]},{"id":"might_3b","cost":2,"icon":"fa-angles-up","name":"Brutal Momentum","tier":3,"angle":-135,"branch":"might","effect":"Reducing a creature to 0 HP grants +10 ft of movement and advantage on your next attack this turn.","prereqs":["might_2"]},{"id":"vit_3","cost":2,"icon":"fa-heart-pulse","name":"Second Wind","tier":3,"angle":45,"branch":"vitality","effect":"Regain 1 HP at the start of each of your turns while below half your maximum HP.","prereqs":["vit_2b"]},{"id":"vit_3b","cost":2,"icon":"fa-arrows-rotate","name":"Regeneration","tier":3,"angle":135,"branch":"vitality","effect":"At the end of a short rest, regain HP equal to your Constitution modifier (minimum 1).","prereqs":["vit_2"]},{"id":"grit_3","cost":2,"icon":"fa-mountain","name":"Unflinching","tier":3,"angle":180,"branch":"grit","effect":"Advantage on saving throws against being frightened; you cannot be moved against your will.","prereqs":["grit_2"]},{"id":"apex","cost":3,"icon":"fa-star","mods":{"maxHp":10,"abilities":{"str":2}},"name":"Unbreakable","tier":4,"angle":0,"branch":"apex","effect":"+2 STR, +10 max HP, and you cannot be knocked prone.","prereqs":["might_3","vit_3"]},{"id":"toll","cost":0,"icon":"fa-explosion","name":"","tier":4,"angle":180,"branch":"apex","effect":"","prereqs":["grit_3"],"concealed":true}],"flavor":"A knot of dull amber glass, warm to the touch. It sits against the sternum and the body starts telling small lies about how tired it is.","module":"Physical Enhancement","rarity":"Uncommon","baseMods":{"maxHp":5,"abilities":{"con":1,"str":2}},"branches":{"apex":"Apex","core":"Core","grit":"Grit","might":"Might","vitality":"Vitality"},"capacity":12,"published":true,"attuneRule":"Requires attunement · occupies 1 of 2 shard slots","baseDetails":[{"l":"Digitization","v":"+1% / tier"}],"baseFeatures":[]}'::jsonb)
  on conflict (id) do update set data = excluded.data;

